"use strict";(self.webpackChunkbed_mega_textbook=self.webpackChunkbed_mega_textbook||[]).push([[996],{749(e,n,i){i.r(n),i.d(n,{assets:()=>c,contentTitle:()=>d,default:()=>m,frontMatter:()=>h,metadata:()=>t,toc:()=>l});const t=JSON.parse('{"id":"semester-1/efmp-302/unit-05/topic-02","title":"Topic 5.2 - What is asked of you, and by whom","description":"The increased focus on teacher accountability, the competing expectations of pupils, parents, heads, districts and the public, and the relationship between a profession\'s status and its recognition.","source":"@site/docs/semester-1/efmp-302/unit-05/topic-02.mdx","sourceDirName":"semester-1/efmp-302/unit-05","slug":"/semester-1/efmp-302/unit-05/topic-02","permalink":"/semester-1/efmp-302/unit-05/topic-02","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"title":"Topic 5.2 - What is asked of you, and by whom","description":"The increased focus on teacher accountability, the competing expectations of pupils, parents, heads, districts and the public, and the relationship between a profession\'s status and its recognition.","course_code":"EFMP-302","unit_no":5,"topic_no":2,"topic_label":"5.2","clo_refs":["SLO:EFMP-302-5-1"],"blooms_summary":"Understand what an increased focus on accountability changes in practice; remember the parties making demands and what each measures; analyse why competing expectations cannot all be satisfied and how status and recognition relate; evaluate which parts of a profession\'s standing a teacher can affect.","est_reading_minutes":23,"translation_status":"draft"},"sidebar":"textbook","previous":{"title":"Topic 5.1 - The conditions you will actually teach in","permalink":"/semester-1/efmp-302/unit-05/topic-01"},"next":{"title":"Topic 5.3 - Professionalism in the digital age","permalink":"/semester-1/efmp-302/unit-05/topic-03"}}');var o=i(4848),a=i(8453),r=i(6606),s=i(6462);const h={title:"Topic 5.2 - What is asked of you, and by whom",description:"The increased focus on teacher accountability, the competing expectations of pupils, parents, heads, districts and the public, and the relationship between a profession's status and its recognition.",course_code:"EFMP-302",unit_no:5,topic_no:2,topic_label:"5.2",clo_refs:["SLO:EFMP-302-5-1"],blooms_summary:"Understand what an increased focus on accountability changes in practice; remember the parties making demands and what each measures; analyse why competing expectations cannot all be satisfied and how status and recognition relate; evaluate which parts of a profession's standing a teacher can affect.",est_reading_minutes:23,translation_status:"draft"},d="Topic 5.2 - What is asked of you, and by whom",c={},l=[{value:"A real classroom situation",id:"a-real-classroom-situation",level:2},{value:"Explanation",id:"explanation",level:2},{value:"The increased focus on teacher accountability",id:"the-increased-focus-on-teacher-accountability",level:3},{value:"High expectations from many stakeholders at once",id:"high-expectations-from-many-stakeholders-at-once",level:3},{value:"Socio-economic status and public recognition",id:"socio-economic-status-and-public-recognition",level:3},{value:"Activity: Four demands, one week",id:"activity-four-demands-one-week",level:2},{value:"Check your understanding",id:"check-your-understanding",level:2},{value:"Summary",id:"summary",level:2},{value:"Self-assessment checklist",id:"self-assessment-checklist",level:2},{value:"Try this at your practicum school",id:"try-this-at-your-practicum-school",level:2},{value:"Summative task",id:"summative-task",level:2},{value:"Further reading",id:"further-reading",level:2}];function u(e){const n={a:"a",blockquote:"blockquote",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",input:"input",li:"li",ol:"ol",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,a.R)(),...e.components},{Figure:i}=n;return i||function(e,n){throw new Error("Expected "+(n?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Figure",!0),(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(r.A,{}),"\n",(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"topic-52---what-is-asked-of-you-and-by-whom",children:"Topic 5.2 - What is asked of you, and by whom"})}),"\n",(0,o.jsx)(n.h2,{id:"a-real-classroom-situation",children:"A real classroom situation"}),"\n",(0,o.jsx)(i,{id:"fig-U5-3",kind:"concept-map",width:"920",height:"470",src:"/img/figures/efmp-302/unit-05/fig-U5-3.svg",alt:"Concept map of a teacher surrounded by six parties making demands - pupils, parents, head, district, examination system and the public - each link labelled with what that party wants and what it actually measures."}),"\n",(0,o.jsx)(n.p,{children:"In one week, Mr Rafiq is told four things."}),"\n",(0,o.jsx)(n.p,{children:"His head tells him the school's Class 10 results must improve. A parent tells him her son is\nbeing pushed too hard and is not sleeping. The district office sends a circular requiring a new\nmonthly assessment return. A newspaper column, which several colleagues have read, says that\ngovernment teachers are paid to do nothing."}),"\n",(0,o.jsx)(n.p,{children:"Every one of these is a legitimate voice with a real interest in his work. No two of them are\nasking for the same thing, and one of them is asking for something incompatible with another.\nHe has one week and one Class 10."}),"\n",(0,o.jsx)(n.h2,{id:"explanation",children:"Explanation"}),"\n",(0,o.jsx)(n.h3,{id:"the-increased-focus-on-teacher-accountability",children:"The increased focus on teacher accountability"}),"\n",(0,o.jsx)(n.p,{children:"Accountability in teaching has grown steadily over the last three decades, in Pakistan and\nalmost everywhere else. Unit 4 gave the mechanisms: standards, appraisal, licensing, inspection.\nThis topic asks what their accumulation does to the person being held accountable."}),"\n",(0,o.jsx)(n.p,{children:"The case for accountability is strong and this unit does not dispute it. A profession that\ncannot be held to account has no claim on public trust, as Unit 1 argued, and in a system where\nteacher absence and unprepared teaching are real problems, the demand for accountability is not\nan insult."}),"\n",(0,o.jsx)(n.p,{children:"What is worth understanding is what accountability does when it arrives without the other half of\nthe bargain. Isor\xe9 (2009), reviewing teacher evaluation across OECD countries, found the tension\nbetween accountability and development to be the central design problem of evaluation systems.\nAccountability mechanisms measure, compare and impose consequences. They do not, by themselves,\nsupply anything that makes the measured work easier to do."}),"\n",(0,o.jsx)(n.p,{children:"So a predictable pattern follows, and you should expect to see it:"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"What is measured becomes what is done."})," If results are measured and understanding is not,\nteaching narrows toward results. Unit 3 made this point about effectiveness; it is the same\nmechanism."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Effort moves from the work to the record of the work."})," The monthly return in Mr Rafiq's week\nis real work that produces no learning."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Accountability without autonomy produces compliance rather than improvement."})," A teacher held\nresponsible for an outcome they are given no power to affect will manage their exposure, which\nis rational."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Hargreaves (2000), tracing the historical phases of teacher professionalism, situates this: the\ndemand for accountability is part of a long movement in how societies relate to teaching, not a\nrecent invention or a local grievance."}),"\n",(0,o.jsx)(n.p,{children:"The practical conclusion for a trainee is narrow and useful. When you meet an accountability\ndemand, ask what it measures and what it supplies. If it measures and supplies nothing, it will\nchange your behaviour without improving your teaching, and knowing that lets you protect the\nteaching."}),"\n",(0,o.jsx)(n.h3,{id:"high-expectations-from-many-stakeholders-at-once",children:"High expectations from many stakeholders at once"}),"\n",(0,o.jsxs)(n.p,{children:["The figure above maps the parties and, crucially, distinguishes ",(0,o.jsx)(n.strong,{children:"what each wants"})," from ",(0,o.jsx)(n.strong,{children:"what\neach measures"}),". Those two are different for almost every party, and the gap is where most of a\nteacher's difficulty lives."]}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Pupils"})," want to be treated fairly and to understand. What they can judge is mostly fairness\nand clarity, not whether the curriculum was covered."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Parents"})," want their child to succeed and be safe. Many measure by marks, because marks are\nthe only signal the system gives them."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The head"})," wants a school that runs and results that hold up. Measures attendance,\ncompliance, and examination outcomes."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The district"})," wants returns filed and standards met. Measures paperwork, because paperwork is\nwhat travels up a system."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The examination system"})," wants coverage of the syllabus. Measures one paper."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"The public"})," wants a profession worth funding. Measures by anecdote and by newspaper column."]}),"\n"]}),"\n",(0,o.jsxs)(n.p,{children:["Three things follow. ",(0,o.jsx)(n.strong,{children:"The demands genuinely conflict"}),": the parent asking Mr Rafiq to ease off\nand the head asking for better results cannot both be satisfied by the same action. ",(0,o.jsx)(n.strong,{children:"No party\nsees the whole job"}),", so each judges from a partial view that feels complete from where they\nstand. And ",(0,o.jsx)(n.strong,{children:"the teacher is the only person positioned to see all of it"}),", which is a\nresponsibility and also the reason the work feels isolating."]}),"\n",(0,o.jsx)(n.p,{children:"What a professional does with this is not satisfy everyone, which is impossible, but decide\nexplicitly whose claim takes priority when they conflict, and be able to say why. Unit 2's\ndilemma material is the tool: name the competing goods, accept that something will be lost, and\nchoose where the loss falls. In Mr Rafiq's case the pupil's welfare and the pupil's results are\nboth his to weigh, and the newspaper column is not a claim on him at all."}),"\n",(0,o.jsx)(n.h3,{id:"socio-economic-status-and-public-recognition",children:"Socio-economic status and public recognition"}),"\n",(0,o.jsx)(n.p,{children:"Demirkasimoglu (2010), reviewing how teacher professionalism has been defined, opens from the\nlong argument over whether teaching is a profession or a semi-profession, given the limits placed\non teacher autonomy and decision-making. That argument is the background to everything in this\nsection: the markers below are the ones that argument is conducted in."}),"\n",(0,o.jsx)(i,{id:"fig-U5-4",kind:"table",width:"900",height:"410",src:"/img/figures/efmp-302/unit-05/fig-U5-4.svg",alt:"Table comparing teaching with medicine, law, engineering and nursing on pay, entry selectivity, autonomy and public recognition, noting that the markers do not move together."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(s.A,{term:"Occupational Status",children:"Occupational status"})," is the standing a society\naccords a line of work: what it pays, who it attracts, how it is spoken about, and how much\nindependence its members are granted."]}),"\n",(0,o.jsx)(n.p,{children:"Teaching's status is uneven rather than simply low, and the figure above is built to show that.\nAgainst medicine or law, teaching in Pakistan typically has lower pay, a less selective entry\nroute and less day-to-day autonomy. Against many other occupations it has greater security,\nsubstantial social respect in some communities, and a moral standing that survives even hostile\nnewspaper columns."}),"\n",(0,o.jsx)(n.p,{children:"This unit cites no research for that comparison, because none was verified while it was written.\nThe pattern is offered as reasoned description consistent with the definitional debate\nDemirkasimoglu reviews, not as measured national figures, and the figure above carries the same\ncaveat on its face. Treat it as a claim to check against your own system, and note that the\nmarkers move independently: an occupation can score well on recognition and badly on autonomy."}),"\n",(0,o.jsx)(n.p,{children:"The relationship between status and recognition runs in both directions, and this is the part\nworth thinking about carefully."}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Status shapes who enters."})," Where teaching is a fallback rather than a first choice, the\nprofession recruits accordingly, and Unit 3's discussion of attitude toward the profession becomes\na live problem rather than an abstraction."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Practice shapes recognition."})," A public forms its view of teachers from the teachers it meets:\nits own, its children's, the one at the gate who did or did not have time to talk. The newspaper\ncolumn that angered Mr Rafiq's colleagues was written by someone with their own school memories."]}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"And recognition is not the same as status."})," A teacher can be genuinely respected in their\ncommunity while the occupation remains poorly paid and weakly trusted nationally. Conflating the\ntwo produces the misconception this section exists to correct: ",(0,o.jsx)(n.em,{children:"a teacher's status is fixed by\nsociety and nothing a teacher does affects it."})," The occupation's structural position is not\nsomething one teacher can shift. The recognition extended to teachers in one community, by the\npeople who deal with them, is affected by what those teachers do every day, and Unit 2's account\nof the profession's collective standing is the same argument."]}),"\n",(0,o.jsx)(n.p,{children:"That is not a call to be satisfied with poor pay and to seek respect instead. Structural\nconditions require structural remedies, and Topic 5.4 is explicit that some things are not within\na teacher's control. It is a statement about which part of the problem is in your hands."}),"\n",(0,o.jsx)(n.h2,{id:"activity-four-demands-one-week",children:"Activity: Four demands, one week"}),"\n",(0,o.jsx)(n.p,{children:"Work in groups of four. Take Mr Rafiq's week from the top of this topic and assign one demand to\neach member: the head's, the parent's, the district's, the newspaper's."}),"\n",(0,o.jsx)(n.p,{children:"Argue your assigned party's case as strongly as you can, in turn, including what that party would\nsay about the others' demands."}),"\n",(0,o.jsx)(n.p,{children:"Then decide as a group: which demands are genuine claims on Mr Rafiq, which are not claims on him\nat all, and in what order should the genuine ones be honoured? You must reach a ranking and be\nable to state the criterion you used."}),"\n",(0,o.jsx)(n.p,{children:"Allow 30 minutes. The most useful disagreement is usually about the newspaper column."}),"\n",(0,o.jsx)(n.h2,{id:"check-your-understanding",children:"Check your understanding"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:["Explain what accountability mechanisms measure and what they do not supply. ",(0,o.jsx)(n.em,{children:"(Understand)"})]}),"\n",(0,o.jsxs)(n.li,{children:["Give two predictable effects of accountability arriving without autonomy. ",(0,o.jsx)(n.em,{children:"(Remember)"})]}),"\n",(0,o.jsxs)(n.li,{children:["For any three stakeholders, state what that party wants and what it actually measures.\n",(0,o.jsx)(n.em,{children:"(Apply)"})]}),"\n",(0,o.jsxs)(n.li,{children:["Explain why no single party is in a position to judge a teacher's whole job, and what follows\nfrom that. ",(0,o.jsx)(n.em,{children:"(Analyze)"})]}),"\n",(0,o.jsxs)(n.li,{children:["Distinguish occupational status from public recognition, and explain why conflating them leads\nteachers to conclude that nothing they do matters. ",(0,o.jsx)(n.em,{children:"(Analyze)"})]}),"\n"]}),"\n",(0,o.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,o.jsx)(n.p,{children:"Accountability in teaching has grown steadily and the case for it is sound. What it does not do\nby itself is supply anything that makes the measured work easier. Where it arrives without\nautonomy or resources, three things follow predictably: what is measured becomes what is done,\neffort shifts from the work to the record of the work, and teachers manage their exposure rather\nthan improving their practice."}),"\n",(0,o.jsx)(n.p,{children:"Many parties make demands on a teacher, and for almost all of them what they want and what they\nmeasure are different things. The demands genuinely conflict, no party sees the whole job, and the\nteacher is the only person who does. The professional response is not to satisfy everyone but to\ndecide whose claim takes priority and be able to justify it."}),"\n",(0,o.jsx)(n.p,{children:"Teaching's status is uneven rather than simply low. Status shapes who enters the profession;\npractice shapes the recognition a community extends to it. The two are not the same, and\nconflating them produces the belief that nothing a teacher does affects how teaching is regarded,\nwhich is false of recognition even where it is true of structural status."}),"\n",(0,o.jsx)(n.h2,{id:"self-assessment-checklist",children:"Self-assessment checklist"}),"\n",(0,o.jsxs)(n.ul,{className:"contains-task-list",children:["\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can state the case for accountability and what it fails to supply."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can predict what accountability without autonomy does to behaviour."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can distinguish what each stakeholder wants from what each measures."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can rank conflicting demands and state the criterion I used."]}),"\n",(0,o.jsxs)(n.li,{className:"task-list-item",children:[(0,o.jsx)(n.input,{type:"checkbox",disabled:!0})," ","I can distinguish status from recognition and say which part is affected by my own practice."]}),"\n"]}),"\n",(0,o.jsx)(n.h2,{id:"try-this-at-your-practicum-school",children:"Try this at your practicum school"}),"\n",(0,o.jsx)(n.p,{children:"Ask three people connected to your practicum school what they think makes a good teacher: a\npupil, a parent if you can, and a teacher or the head."}),"\n",(0,o.jsx)(n.p,{children:"Write half a page comparing the three answers against what each of them is actually in a position\nto observe. The usual finding is that each answer is accurate about the part they see and\nincomplete about the rest, which is the topic's central point arriving as evidence rather than\nassertion."}),"\n",(0,o.jsx)(n.h2,{id:"summative-task",children:"Summative task"}),"\n",(0,o.jsx)(n.p,{children:"Write 450 to 500 words."}),"\n",(0,o.jsxs)(n.blockquote,{children:["\n",(0,o.jsx)(n.p,{children:"Mr Rafiq has four demands and one week. Decide what he should do, and justify the order."}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"Name each demand, say what the party wants and what it measures, identify which are genuine claims\non him and which are not, and give a ranking with the criterion it rests on. Then address the\nobjection that ignoring the head's demand is not realistic for someone whose confirmation and\ntransfer depend on that head's report."}),"\n",(0,o.jsx)(n.p,{children:(0,o.jsx)(n.strong,{children:"Mini-rubric"})}),"\n",(0,o.jsxs)(n.table,{children:[(0,o.jsx)(n.thead,{children:(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.th,{children:"Criterion"}),(0,o.jsx)(n.th,{children:"What a strong response does"})]})}),(0,o.jsxs)(n.tbody,{children:[(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:"Analysis of demands (Apply)"}),(0,o.jsx)(n.td,{children:"Separates what each party wants from what it measures, for every demand"})]}),(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:"Identification of non-claims"}),(0,o.jsx)(n.td,{children:"Argues which demands are not claims on him at all, rather than ranking all four"})]}),(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:(0,o.jsx)(n.strong,{children:"Justified ranking (Evaluate)"})}),(0,o.jsx)(n.td,{children:(0,o.jsx)(n.strong,{children:"States the criterion the ranking rests on and defends choosing it, rather than asserting an order"})})]}),(0,o.jsxs)(n.tr,{children:[(0,o.jsx)(n.td,{children:(0,o.jsx)(n.strong,{children:"Realism about consequence (Analyze)"})}),(0,o.jsx)(n.td,{children:(0,o.jsx)(n.strong,{children:"Engages with the career cost of deprioritising the head, rather than recommending a course that ignores it"})})]})]})]}),"\n",(0,o.jsx)(n.h2,{id:"further-reading",children:"Further reading"}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:["Isor\xe9, M. (2009). ",(0,o.jsx)(n.em,{children:"Teacher evaluation: Current practices in OECD countries and a literature\nreview"})," (OECD Education Working Papers No. 23). OECD Publishing.\n",(0,o.jsx)(n.a,{href:"https://files.eric.ed.gov/fulltext/ED530786.pdf",children:"https://files.eric.ed.gov/fulltext/ED530786.pdf"})]}),"\n",(0,o.jsxs)(n.li,{children:["Hargreaves, A. (2000). Four ages of professionalism and professional learning. ",(0,o.jsx)(n.em,{children:"Teachers and\nTeaching, 6"}),"(2), 151-182. ",(0,o.jsx)(n.a,{href:"https://doi.org/10.1080/713698714",children:"https://doi.org/10.1080/713698714"})]}),"\n",(0,o.jsxs)(n.li,{children:['Demirkasimoglu, N. (2010). Defining "teacher professionalism" from different perspectives.\n',(0,o.jsx)(n.em,{children:"Procedia - Social and Behavioral Sciences, 9"}),", 2047-2051.\n",(0,o.jsx)(n.a,{href:"https://doi.org/10.1016/j.sbspro.2010.12.444",children:"https://doi.org/10.1016/j.sbspro.2010.12.444"})]}),"\n"]})]})}function m(e={}){const{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},6462(e,n,i){i.d(n,{A:()=>a});i(6540);const t=JSON.parse('[{"term":"Educational Psychology","definition_en":"The study of how people learn in educational settings, and how teaching can be organised to help learning.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1 \u06a9\u06c1 \u0644\u0648\u06af \u062a\u0639\u0644\u06cc\u0645\u06cc \u0645\u0627\u062d\u0648\u0644 \u0645\u06cc\u06ba \u06a9\u06cc\u0633\u06d2 \u0633\u06cc\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u062a\u062f\u0631\u06cc\u0633 \u06a9\u0648 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06cc\u0633\u06d2 \u062a\u0631\u062a\u06cc\u0628 \u062f\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Cognition","definition_en":"The mental processes involved in gaining knowledge and understanding - such as attention, memory, and reasoning.","definition_ur":"\u0639\u0644\u0645 \u0627\u0648\u0631 \u0641\u06c1\u0645 \u062d\u0627\u0635\u0644 \u06a9\u0631\u0646\u06d2 \u0645\u06cc\u06ba \u0634\u0627\u0645\u0644 \u0630\u06c1\u0646\u06cc \u0639\u0645\u0644 - \u062c\u06cc\u0633\u06d2 \u062a\u0648\u062c\u06c1\u060c \u06cc\u0627\u062f\u062f\u0627\u0634\u062a \u0627\u0648\u0631 \u0627\u0633\u062a\u062f\u0644\u0627\u0644\u06d4"},{"term":"Profession","definition_en":"An occupation that requires specialized training, follows a code of conduct, and is accountable to a professional community - such as teaching, medicine, or law.","definition_ur":"\u067e\u06cc\u0634\u06c1 \u0627\u06cc\u06a9 \u0627\u06cc\u0633\u0627 \u06a9\u0627\u0645 \u06c1\u06d2 \u062c\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062e\u0635\u0648\u0635\u06cc \u062a\u0631\u0628\u06cc\u062a \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u062c\u0648 \u0627\u06cc\u06a9 \u0636\u0627\u0628\u0637\u06c1 \u0627\u062e\u0644\u0627\u0642 \u06a9\u06cc \u067e\u06cc\u0631\u0648\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u062c\u0648 \u0627\u067e\u0646\u06cc \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0628\u0631\u0627\u062f\u0631\u06cc \u06a9\u06d2 \u0633\u0627\u0645\u0646\u06d2 \u062c\u0648\u0627\u0628\u062f\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 - \u062c\u06cc\u0633\u06d2 \u062a\u062f\u0631\u06cc\u0633\u060c \u0637\u0628\u060c \u06cc\u0627 \u0648\u06a9\u0627\u0644\u062a\u06d4"},{"term":"Professionalism","definition_en":"The quality of conducting oneself according to the standards, ethics, and responsibilities expected of a profession.","definition_ur":"\u067e\u06cc\u0634\u06c1 \u0648\u0627\u0631\u06cc\u062a \u0633\u06d2 \u0645\u0631\u0627\u062f \u06a9\u0633\u06cc \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0645\u062a\u0648\u0642\u0639 \u0645\u0639\u06cc\u0627\u0631\u0627\u062a\u060c \u0627\u062e\u0644\u0627\u0642\u06cc\u0627\u062a \u0627\u0648\u0631 \u0630\u0645\u06c1 \u062f\u0627\u0631\u06cc\u0648\u06ba \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0627\u067e\u0646\u06d2 \u0622\u067e \u06a9\u0648 \u0686\u0644\u0627\u0646\u06d2 \u06a9\u06cc \u062e\u0648\u0628\u06cc \u06c1\u06d2\u06d4"},{"term":"Professional Ethics","definition_en":"The set of moral principles and standards of conduct that guide how members of a profession should behave toward those they serve and each other.","definition_ur":"\u0627\u062e\u0644\u0627\u0642\u06cc \u0627\u0635\u0648\u0644\u0648\u06ba \u0627\u0648\u0631 \u0636\u0627\u0628\u0637\u06c1 \u0627\u062e\u0644\u0627\u0642 \u06a9\u0627 \u0648\u06c1 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062c\u0648 \u06a9\u0633\u06cc \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0627\u0631\u06a9\u0627\u0646 \u06a9\u06d2 \u0637\u0631\u0632\u0650 \u0639\u0645\u0644 \u06a9\u06cc \u0631\u06c1\u0646\u0645\u0627\u0626\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2 - \u0627\u064f\u0646 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0646 \u06a9\u06cc \u0648\u06c1 \u062e\u062f\u0645\u062a \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be\u06d4"},{"term":"Ethical Dilemma","definition_en":"A situation with no clearly right answer, where a professional must choose between competing values or responsibilities.","definition_ur":"\u0627\u06cc\u0633\u06cc \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u062c\u0633 \u06a9\u0627 \u06a9\u0648\u0626\u06cc \u0648\u0627\u0636\u062d \u0637\u0648\u0631 \u067e\u0631 \u062f\u0631\u0633\u062a \u062c\u0648\u0627\u0628 \u0646\u06c1 \u06c1\u0648\u060c \u062c\u06c1\u0627\u06ba \u0627\u06cc\u06a9 \u067e\u06cc\u0634\u06c1 \u0648\u0631 \u06a9\u0648 \u0628\u0627\u06c1\u0645 \u0645\u062a\u0635\u0627\u062f\u0645 \u0627\u0642\u062f\u0627\u0631 \u06cc\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631\u06cc\u0648\u06ba \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0627\u0646\u062a\u062e\u0627\u0628 \u06a9\u0631\u0646\u0627 \u067e\u0691\u06d2\u06d4"},{"term":"Continuous Professional Development","definition_en":"Ongoing learning and growth a teacher pursues throughout their career, through both formal activities (courses, conferences) and reflective practice (journals, peer feedback).","definition_ur":"\u0648\u06c1 \u0645\u0633\u0644\u0633\u0644 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0627\u0648\u0631 \u062a\u0631\u0642\u06cc \u06a9\u0627 \u0639\u0645\u0644 \u062c\u0648 \u0627\u06cc\u06a9 \u0627\u0633\u062a\u0627\u062f \u0627\u067e\u0646\u06d2 \u067e\u0648\u0631\u06d2 \u06a9\u06cc\u0631\u06cc\u0626\u0631 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u062c\u0627\u0631\u06cc \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2 - \u0631\u0633\u0645\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc\u0648\u06ba (\u06a9\u0648\u0631\u0633\u0632\u060c \u06a9\u0627\u0646\u0641\u0631\u0646\u0633\u06cc\u06ba) \u0627\u0648\u0631 \u063a\u0648\u0631 \u0648 \u0641\u06a9\u0631 \u067e\u0631 \u0645\u0628\u0646\u06cc \u0639\u0645\u0644 (\u0688\u0627\u0626\u0631\u06cc \u0646\u0648\u06cc\u0633\u06cc\u060c \u06c1\u0645 \u0639\u0645\u0631 \u062a\u0627\u062b\u0631\u0627\u062a) \u062f\u0648\u0646\u0648\u06ba \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2\u06d4"},{"term":"Code of Ethical Conduct","definition_en":"A written statement of what a profession\'s members owe and to whom, usually organised by the party the obligation is owed to: students, one\'s own practice, parents and community, and colleagues.","definition_ur":"\u0627\u06cc\u06a9 \u062a\u062d\u0631\u06cc\u0631\u06cc \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u062c\u0648 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0627\u0641\u0631\u0627\u062f \u067e\u0631 \u06a9\u06cc\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631\u06cc\u0627\u06ba \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u06a9\u0646 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u06cc\u06ba\u060c \u0639\u0645\u0648\u0645\u0627\u064b \u0627\u0633 \u0641\u0631\u06cc\u0642 \u06a9\u06d2 \u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u06d2 \u062a\u0631\u062a\u06cc\u0628 \u062f\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2 \u062c\u0633 \u06a9\u0627 \u062d\u0642 \u06c1\u06d2: \u0634\u0627\u06af\u0631\u062f\u060c \u0627\u067e\u0646\u0627 \u0639\u0645\u0644\u060c \u0648\u0627\u0644\u062f\u06cc\u0646 \u0627\u0648\u0631 \u0645\u0639\u0627\u0634\u0631\u06c1\u060c \u0627\u0648\u0631 \u06c1\u0645 \u067e\u06cc\u0634\u06c1 \u0627\u0641\u0631\u0627\u062f\u06d4"},{"term":"Reflective Decision Making","definition_en":"The habit of treating your own professional decisions as things to be examined rather than defended: structured, actively seeking evidence that the decision was wrong, and applied to routine cases rather than only dramatic ones.","definition_ur":"\u0627\u067e\u0646\u06d2 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0641\u06cc\u0635\u0644\u0648\u06ba \u06a9\u0648 \u062f\u0641\u0627\u0639 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u062c\u0627\u0646\u0686 \u06a9\u06d2 \u0644\u0627\u0626\u0642 \u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06cc \u0639\u0627\u062f\u062a: \u0645\u0646\u0638\u0645 \u0627\u0646\u062f\u0627\u0632 \u0645\u06cc\u06ba\u060c \u0627\u0633 \u0634\u06c1\u0627\u062f\u062a \u06a9\u06cc \u062a\u0644\u0627\u0634 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06c1 \u0641\u06cc\u0635\u0644\u06c1 \u063a\u0644\u0637 \u062a\u06be\u0627\u060c \u0627\u0648\u0631 \u0635\u0631\u0641 \u063a\u06cc\u0631 \u0645\u0639\u0645\u0648\u0644\u06cc \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0631\u0648\u0632\u0645\u0631\u06c1 \u0645\u0639\u0627\u0645\u0644\u0627\u062a \u067e\u0631 \u0628\u06be\u06cc \u0644\u0627\u06af\u0648\u06d4"},{"term":"Teacher Effectiveness","definition_en":"The effect a teacher has on what their pupils learn. Definitions in use differ over which effects count: measured attainment gain, observed classroom practice, or the wider range of learner outcomes.","definition_ur":"\u0648\u06c1 \u0627\u062b\u0631 \u062c\u0648 \u0627\u0633\u062a\u0627\u062f \u0627\u067e\u0646\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u067e\u0631 \u0688\u0627\u0644\u062a\u0627 \u06c1\u06d2\u06d4 \u0631\u0627\u0626\u062c \u062a\u0639\u0631\u06cc\u0641\u06cc\u06ba \u0627\u0633 \u0628\u0627\u062a \u067e\u0631 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06cc\u06ba \u06a9\u06c1 \u06a9\u0648\u0646 \u0633\u06d2 \u0627\u062b\u0631\u0627\u062a \u0634\u0645\u0627\u0631 \u06c1\u0648\u06ba: \u0646\u0627\u067e\u06cc \u06af\u0626\u06cc \u06a9\u0627\u0631\u06a9\u0631\u062f\u06af\u06cc \u0645\u06cc\u06ba \u0627\u0636\u0627\u0641\u06c1\u060c \u0645\u0634\u0627\u06c1\u062f\u06c1 \u0634\u062f\u06c1 \u062c\u0645\u0627\u0639\u062a\u06cc \u0639\u0645\u0644\u060c \u06cc\u0627 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u0648\u06ba \u06a9\u06d2 \u0648\u0633\u06cc\u0639 \u062a\u0631 \u0646\u062a\u0627\u0626\u062c\u06d4"},{"term":"Verbal Communication","definition_en":"The words themselves: what a teacher says, how it is structured, and whether the person hearing it can follow it. In a classroom it explains, instructs, questions and responds.","definition_ur":"\u0627\u0644\u0641\u0627\u0638 \u0628\u0630\u0627\u062a\u0650 \u062e\u0648\u062f: \u0627\u0633\u062a\u0627\u062f \u06a9\u06cc\u0627 \u06a9\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u0633 \u062a\u0631\u062a\u06cc\u0628 \u0633\u06d2 \u06a9\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u06a9\u06cc\u0627 \u0633\u0646\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0633\u06d2 \u0633\u0645\u062c\u06be \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4 \u062c\u0645\u0627\u0639\u062a \u0645\u06cc\u06ba \u06cc\u06c1 \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u062a\u0627\u060c \u06c1\u062f\u0627\u06cc\u062a \u062f\u06cc\u062a\u0627\u060c \u0633\u0648\u0627\u0644 \u06a9\u0631\u062a\u0627 \u0627\u0648\u0631 \u062c\u0648\u0627\u0628 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Non-verbal Communication","definition_en":"Everything carried outside the words: proximity, body orientation, gaze and eye contact, facial expression, gesture and vocal variety. Learners read these fast and follow them when they contradict the words.","definition_ur":"\u0648\u06c1 \u0633\u0628 \u06a9\u0686\u06be \u062c\u0648 \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u0628\u0627\u06c1\u0631 \u0645\u0646\u062a\u0642\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2: \u0642\u0631\u0628\u062a\u060c \u062c\u0633\u0645 \u06a9\u0627 \u0631\u062e\u060c \u0646\u06af\u0627\u06c1 \u0627\u0648\u0631 \u0622\u0646\u06a9\u06be \u06a9\u0627 \u0645\u0644\u0627\u067e\u060c \u0686\u06c1\u0631\u06d2 \u06a9\u06d2 \u062a\u0627\u062b\u0631\u0627\u062a\u060c \u0627\u0634\u0627\u0631\u06d2 \u0627\u0648\u0631 \u0622\u0648\u0627\u0632 \u06a9\u0627 \u0627\u062a\u0627\u0631 \u0686\u0691\u06be\u0627\u0624\u06d4 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0646\u06c1\u06cc\u06ba \u062a\u06cc\u0632\u06cc \u0633\u06d2 \u067e\u0691\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u062a\u0636\u0627\u062f \u06a9\u06cc \u0635\u0648\u0631\u062a \u0645\u06cc\u06ba \u0627\u0646\u06c1\u06cc \u06a9\u06cc \u067e\u06cc\u0631\u0648\u06cc \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Professional Standards","definition_en":"A documented statement of the knowledge, values and practice expected of a competent member of a profession, written specifically enough that someone can judge whether it has been met.","definition_ur":"\u0627\u06cc\u06a9 \u062a\u062d\u0631\u06cc\u0631\u06cc \u0628\u06cc\u0627\u0646 \u062c\u0648 \u0627\u0633 \u0639\u0644\u0645\u060c \u0627\u0642\u062f\u0627\u0631 \u0627\u0648\u0631 \u0639\u0645\u0644 \u06a9\u0648 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u067e\u06cc\u0634\u06d2 \u06a9\u06d2 \u0627\u06cc\u06a9 \u0627\u06c1\u0644 \u0641\u0631\u062f \u0633\u06d2 \u0645\u062a\u0648\u0642\u0639 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u062a\u0646\u0627 \u0645\u062e\u0635\u0648\u0635 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u067e\u0631\u06a9\u06be \u0633\u06a9\u06d2 \u06a9\u06c1 \u0648\u06c1 \u067e\u0648\u0631\u0627 \u06c1\u0648\u0627 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"National Professional Standards for Teachers","definition_en":"Pakistan\'s framework of ten teaching standards, issued by the Ministry of Education in 2009 with UNESCO and USAID support. Each standard is divided into knowledge and understanding, dispositions, and performance and skills, with indicators beneath.","definition_ur":"\u067e\u0627\u06a9\u0633\u062a\u0627\u0646 \u06a9\u06d2 \u062f\u0633 \u062a\u062f\u0631\u06cc\u0633\u06cc \u0645\u0639\u06cc\u0627\u0631\u0627\u062a \u06a9\u0627 \u0688\u06be\u0627\u0646\u0686\u06c1\u060c \u062c\u0648 \u0648\u0632\u0627\u0631\u062a\u0650 \u062a\u0639\u0644\u06cc\u0645 \u0646\u06d2 2009 \u0645\u06cc\u06ba \u06cc\u0648\u0646\u06cc\u0633\u06a9\u0648 \u0627\u0648\u0631 \u06cc\u0648 \u0627\u06cc\u0633 \u0627\u06cc\u0688 \u06a9\u06d2 \u062a\u0639\u0627\u0648\u0646 \u0633\u06d2 \u062c\u0627\u0631\u06cc \u06a9\u06cc\u0627\u06d4 \u06c1\u0631 \u0645\u0639\u06cc\u0627\u0631 \u0639\u0644\u0645 \u0648 \u0641\u06c1\u0645\u060c \u0631\u062c\u062d\u0627\u0646\u0627\u062a\u060c \u0627\u0648\u0631 \u06a9\u0627\u0631\u06a9\u0631\u062f\u06af\u06cc \u0648 \u0645\u06c1\u0627\u0631\u062a \u0645\u06cc\u06ba \u062a\u0642\u0633\u06cc\u0645 \u06c1\u06d2\u060c \u062c\u0646 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u0627\u0634\u0627\u0631\u06cc\u06d2 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Teacher Licensing","definition_en":"Permission to practise as a teacher, issued by an authority, usually time-limited and renewable. It differs from certification, which confirms that a person completed the required preparation.","definition_ur":"\u06a9\u0633\u06cc \u0645\u062c\u0627\u0632 \u0627\u062f\u0627\u0631\u06d2 \u06a9\u06cc \u062c\u0627\u0646\u0628 \u0633\u06d2 \u062a\u062f\u0631\u06cc\u0633 \u06a9\u06cc \u0627\u062c\u0627\u0632\u062a\u060c \u062c\u0648 \u0639\u0645\u0648\u0645\u0627\u064b \u0645\u0642\u0631\u0631\u06c1 \u0645\u062f\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0648\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u0642\u0627\u0628\u0644\u0650 \u062a\u062c\u062f\u06cc\u062f \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4 \u06cc\u06c1 \u0633\u0646\u062f \u0628\u0646\u062f\u06cc \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06d2\u060c \u062c\u0648 \u0635\u0631\u0641 \u0645\u0637\u0644\u0648\u0628\u06c1 \u062a\u06cc\u0627\u0631\u06cc \u0645\u06a9\u0645\u0644 \u06c1\u0648\u0646\u06d2 \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Burnout","definition_en":"What chronic, unresolved demand produces over time, with three dimensions: exhaustion, cynicism or distancing from the work, and a reduced sense of accomplishment. It differs from stress, which is episodic and resolves when the demand passes.","definition_ur":"\u0648\u06c1 \u06a9\u06cc\u0641\u06cc\u062a \u062c\u0648 \u0645\u0633\u0644\u0633\u0644 \u0627\u0648\u0631 \u063a\u06cc\u0631 \u062d\u0644 \u0634\u062f\u06c1 \u062a\u0642\u0627\u0636\u0648\u06ba \u0633\u06d2 \u0648\u0642\u062a \u06a9\u06d2 \u0633\u0627\u062a\u06be \u067e\u06cc\u062f\u0627 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u062a\u06cc\u0646 \u067e\u06c1\u0644\u0648 \u06c1\u06cc\u06ba: \u062a\u06be\u06a9\u0646\u060c \u06a9\u0627\u0645 \u0633\u06d2 \u0628\u06cc\u0632\u0627\u0631\u06cc \u06cc\u0627 \u062f\u0648\u0631\u06cc\u060c \u0627\u0648\u0631 \u06cc\u06c1 \u0627\u062d\u0633\u0627\u0633 \u06a9\u06c1 \u06a9\u0686\u06be \u0641\u0631\u0642 \u0646\u06c1\u06cc\u06ba \u067e\u0691\u062a\u0627\u06d4 \u06cc\u06c1 \u062f\u0628\u0627\u0624 \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06d2\u060c \u062c\u0648 \u0648\u0642\u062a\u06cc \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u062a\u0642\u0627\u0636\u0627 \u062e\u062a\u0645 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u062e\u062a\u0645 \u06c1\u0648 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Multi-grade Classroom","definition_en":"A classroom in which one teacher is responsible for pupils of two or more grade levels at the same time, in the same room. Common wherever enrolment is small or teachers few, and requiring skills most teacher preparation does not teach.","definition_ur":"\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u062a\u0627\u062f \u0627\u06cc\u06a9 \u06c1\u06cc \u0648\u0642\u062a \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06c1\u06cc \u06a9\u0645\u0631\u06d2 \u0645\u06cc\u06ba \u062f\u0648 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u062c\u0627\u062a \u06a9\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u06cc\u06c1 \u0648\u06c1\u0627\u06ba \u0639\u0627\u0645 \u06c1\u06d2 \u062c\u06c1\u0627\u06ba \u062f\u0627\u062e\u0644\u06d2 \u06a9\u0645 \u06c1\u0648\u06ba \u06cc\u0627 \u0627\u0633\u0627\u062a\u0630\u06c1 \u06a9\u0645\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0648\u06c1 \u0645\u06c1\u0627\u0631\u062a\u06cc\u06ba \u062f\u0631\u06a9\u0627\u0631 \u06c1\u06cc\u06ba \u062c\u0648 \u0632\u06cc\u0627\u062f\u06c1 \u062a\u0631 \u062a\u0631\u0628\u06cc\u062a \u0645\u06cc\u06ba \u0646\u06c1\u06cc\u06ba \u0633\u06a9\u06be\u0627\u0626\u06cc \u062c\u0627\u062a\u06cc\u06ba\u06d4"},{"term":"Occupational Status","definition_en":"The standing a society accords a line of work: what it pays, who it attracts, how it is spoken about, and how much independence its members are granted. It is distinct from the recognition individual practitioners earn in their own community.","definition_ur":"\u0648\u06c1 \u0645\u0642\u0627\u0645 \u062c\u0648 \u0645\u0639\u0627\u0634\u0631\u06c1 \u06a9\u0633\u06cc \u067e\u06cc\u0634\u06d2 \u06a9\u0648 \u062f\u06cc\u062a\u0627 \u06c1\u06d2: \u0627\u0633 \u06a9\u06cc \u062a\u0646\u062e\u0648\u0627\u06c1\u060c \u0627\u0633 \u06a9\u06cc \u062c\u0627\u0646\u0628 \u0631\u0627\u063a\u0628 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0641\u0631\u0627\u062f\u060c \u0627\u0633 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u06af\u0641\u062a\u06af\u0648\u060c \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0627\u0631\u06a9\u0627\u0646 \u06a9\u0648 \u062f\u06cc \u062c\u0627\u0646\u06d2 \u0648\u0627\u0644\u06cc \u062e\u0648\u062f\u0645\u062e\u062a\u0627\u0631\u06cc\u06d4 \u06cc\u06c1 \u0627\u0633 \u067e\u0630\u06cc\u0631\u0627\u0626\u06cc \u0633\u06d2 \u0627\u0644\u06af \u06c1\u06d2 \u062c\u0648 \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u0627\u06c1\u0644\u06a9\u0627\u0631 \u0627\u067e\u0646\u06cc \u0628\u0631\u0627\u062f\u0631\u06cc \u0645\u06cc\u06ba \u06a9\u0645\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Professional Learning Community","definition_en":"A group of teachers in the same school who meet regularly to examine their own practice and their pupils\' learning, with a shared focus and an expectation that what is discussed is acted on.","definition_ur":"\u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u06a9\u0648\u0644 \u06a9\u06d2 \u0627\u0633\u0627\u062a\u0630\u06c1 \u06a9\u0627 \u06af\u0631\u0648\u06c1 \u062c\u0648 \u0628\u0627\u0642\u0627\u0639\u062f\u06af\u06cc \u0633\u06d2 \u0645\u0644 \u06a9\u0631 \u0627\u067e\u0646\u06d2 \u0639\u0645\u0644 \u0627\u0648\u0631 \u0627\u067e\u0646\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u062a\u0627 \u06c1\u06d2\u060c \u0627\u06cc\u06a9 \u0645\u0634\u062a\u0631\u06a9\u06c1 \u062a\u0648\u062c\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0627\u0648\u0631 \u0627\u0633 \u062a\u0648\u0642\u0639 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06c1 \u062c\u0648 \u0632\u06cc\u0631\u0650 \u0628\u062d\u062b \u0622\u0626\u06d2 \u0627\u0633 \u067e\u0631 \u0639\u0645\u0644 \u0628\u06be\u06cc \u06c1\u0648\u06d4"},{"term":"Reflective Practice","definition_en":"The disciplined examination of your own teaching against evidence, including your pupils\' experience of it and a colleague\'s view of it. It is a professional method rather than a disposition, and it is not the same as keeping a diary of feelings.","definition_ur":"\u0634\u06c1\u0627\u062f\u062a \u06a9\u06cc \u0631\u0648\u0634\u0646\u06cc \u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u062a\u062f\u0631\u06cc\u0633 \u06a9\u0627 \u0645\u0646\u0638\u0645 \u062c\u0627\u0626\u0632\u06c1\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u062a\u062c\u0631\u0628\u06c1 \u0627\u0648\u0631 \u06a9\u0633\u06cc \u06c1\u0645 \u067e\u06cc\u0634\u06c1 \u06a9\u06cc \u0631\u0627\u0626\u06d2 \u0628\u06be\u06cc \u0634\u0627\u0645\u0644 \u06c1\u0648\u06d4 \u06cc\u06c1 \u0627\u06cc\u06a9 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631 \u06c1\u06d2\u060c \u0645\u062d\u0636 \u0627\u06cc\u06a9 \u0631\u062c\u062d\u0627\u0646 \u0646\u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u06cc\u06c1 \u062c\u0630\u0628\u0627\u062a \u06a9\u06cc \u0688\u0627\u0626\u0631\u06cc \u0631\u06a9\u06be\u0646\u06d2 \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u06d2\u06d4"},{"term":"Professional Development Plan","definition_en":"A short written statement, ideally one page, of what a teacher intends to get better at, how, and how they will know: the gap, the evidence for it, one goal, the activity, the evidence of change, and a review date.","definition_ur":"\u0627\u06cc\u06a9 \u0645\u062e\u062a\u0635\u0631 \u062a\u062d\u0631\u06cc\u0631\u06cc \u0628\u06cc\u0627\u0646\u060c \u0628\u06c1\u062a\u0631 \u06c1\u06d2 \u06a9\u06c1 \u0627\u06cc\u06a9 \u0635\u0641\u062d\u06d2 \u06a9\u0627\u060c \u06a9\u06c1 \u0627\u0633\u062a\u0627\u062f \u06a9\u0633 \u0686\u06cc\u0632 \u0645\u06cc\u06ba \u0628\u06c1\u062a\u0631\u06cc \u0686\u0627\u06c1\u062a\u0627 \u06c1\u06d2\u060c \u06a9\u06cc\u0633\u06d2\u060c \u0627\u0648\u0631 \u06a9\u06cc\u0633\u06d2 \u062c\u0627\u0646\u06d2 \u06af\u0627: \u06a9\u0645\u06cc\u060c \u0627\u0633 \u06a9\u06cc \u0634\u06c1\u0627\u062f\u062a\u060c \u0627\u06cc\u06a9 \u06c1\u062f\u0641\u060c \u0633\u0631\u06af\u0631\u0645\u06cc\u060c \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u06cc \u0634\u06c1\u0627\u062f\u062a\u060c \u0627\u0648\u0631 \u062c\u0627\u0626\u0632\u06d2 \u06a9\u06cc \u062a\u0627\u0631\u06cc\u062e\u06d4"},{"term":"Behaviourism","definition_en":"The theory that learning is a change in observable behaviour shaped by the interaction between a stimulus and a response, and by the reinforcement that follows.","definition_ur":"\u0648\u06c1 \u0646\u0638\u0631\u06cc\u06c1 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0645\u0634\u0627\u06c1\u062f\u06c1 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0631\u0648\u06cc\u06d2 \u0645\u06cc\u06ba \u062a\u0628\u062f\u06cc\u0644\u06cc \u06c1\u06d2 \u062c\u0648 \u0645\u062d\u0631\u06a9 \u0627\u0648\u0631 \u0631\u062f\u0639\u0645\u0644 \u06a9\u06d2 \u0628\u0627\u06c1\u0645 \u062a\u0639\u0627\u0645\u0644 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u0628\u0639\u062f \u0622\u0646\u06d2 \u0648\u0627\u0644\u06cc \u062a\u0642\u0648\u06cc\u062a \u0633\u06d2 \u0634\u06a9\u0644 \u0644\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Cognitivism","definition_en":"The theory that learning is the reorganisation of mental structures: the mind processes new information against what it already knows and reshapes its internal understanding.","definition_ur":"\u0648\u06c1 \u0646\u0638\u0631\u06cc\u06c1 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0630\u06c1\u0646\u06cc \u0688\u06be\u0627\u0646\u0686\u0648\u06ba \u06a9\u06cc \u0646\u0626\u06cc \u062a\u0631\u062a\u06cc\u0628 \u06c1\u06d2: \u0630\u06c1\u0646 \u0646\u0626\u06cc \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u06a9\u0627 \u0645\u0639\u0627\u0645\u0644\u06c1 \u0627\u0633 \u06a9\u06d2 \u067e\u06c1\u0644\u06d2 \u0633\u06d2 \u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0645 \u06a9\u06d2 \u062e\u0644\u0627\u0641 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u067e\u0646\u06cc \u0627\u0646\u062f\u0631\u0648\u0646\u06cc \u0633\u0645\u062c\u06be \u06a9\u0648 \u0646\u0626\u06cc \u0634\u06a9\u0644 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Constructivism","definition_en":"The theory that learning is the active construction of personal meaning by the learner, rather than the transfer of intact knowledge from teacher to pupil.","definition_ur":"\u0648\u06c1 \u0646\u0638\u0631\u06cc\u06c1 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06a9\u06cc \u0637\u0631\u0641 \u0633\u06d2 \u0630\u0627\u062a\u06cc \u0645\u0639\u0646\u06cc \u06a9\u06cc \u0641\u0639\u0627\u0644 \u062a\u0639\u0645\u06cc\u0631 \u06c1\u06d2\u060c \u0646\u06c1 \u06a9\u06c1 \u0627\u0633\u062a\u0627\u062f \u0633\u06d2 \u0634\u0627\u06af\u0631\u062f \u062a\u06a9 \u0645\u06a9\u0645\u0644 \u0639\u0644\u0645 \u0645\u0646\u062a\u0642\u0644 \u06c1\u0648\u0646\u0627\u06d4"},{"term":"Classroom management","definition_en":"The set of proactive teacher actions whose purpose is to create and maintain the conditions in which student learning can happen.","definition_ur":"\u0627\u0633\u062a\u0627\u062f \u06a9\u06cc \u0627\u06cc\u0633\u06cc \u0641\u0639\u0627\u0644 \u06a9\u0627\u0631\u0631\u0648\u0627\u0626\u06cc\u0648\u06ba \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062c\u0633 \u06a9\u0627 \u0645\u0642\u0635\u062f \u0627\u06cc\u0633\u06cc \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u0646\u0627 \u06c1\u06d2 \u062c\u0633 \u0645\u06cc\u06ba \u0634\u0627\u06af\u0631\u062f \u0633\u06cc\u06a9\u06be \u0633\u06a9\u06cc\u06ba\u06d4"},{"term":"Discipline","definition_en":"The reactive teacher response after a pupil has breached a classroom norm: the reminder, the consequence, or the conversation that restores the norm.","definition_ur":"\u0634\u0627\u06af\u0631\u062f \u06a9\u06d2 \u06a9\u0644\u0627\u0633 \u06a9\u06d2 \u0627\u0635\u0648\u0644 \u062a\u0648\u0691\u0646\u06d2 \u06a9\u06d2 \u0628\u0639\u062f \u0627\u0633\u062a\u0627\u062f \u06a9\u06cc \u0631\u062f\u0639\u0645\u0644\u06cc \u06a9\u0627\u0631\u0631\u0648\u0627\u0626\u06cc: \u06cc\u0627\u062f \u062f\u06c1\u0627\u0646\u06cc\u060c \u0646\u062a\u06cc\u062c\u06c1\u060c \u06cc\u0627 \u0648\u06c1 \u06af\u0641\u062a\u06af\u0648 \u062c\u0648 \u0627\u0635\u0648\u0644 \u0628\u062d\u0627\u0644 \u06a9\u0631\u06d2\u06d4"},{"term":"Physical environment","definition_en":"The material features of a classroom a teacher can arrange or influence: furniture, displays, resources, lighting, and the use of wall and floor space.","definition_ur":"\u06a9\u0644\u0627\u0633 \u06a9\u06cc \u0648\u06c1 \u0645\u0627\u062f\u06cc \u062e\u0635\u0648\u0635\u06cc\u0627\u062a \u062c\u0648 \u0627\u0633\u062a\u0627\u062f \u062a\u0631\u062a\u06cc\u0628 \u062f\u06d2 \u0633\u06a9\u062a\u0627 \u06c1\u06d2 \u06cc\u0627 \u067e\u0631 \u0627\u062b\u0631 \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u06c1\u06d2: \u0641\u0631\u0646\u06cc\u0686\u0631\u060c \u0646\u0645\u0627\u0626\u0634\u06cc\u06ba\u060c \u0648\u0633\u0627\u0626\u0644\u060c \u0631\u0648\u0634\u0646\u06cc\u060c \u0627\u0648\u0631 \u062f\u06cc\u0648\u0627\u0631 \u0627\u0648\u0631 \u0641\u0631\u0634 \u06a9\u0627 \u0627\u0633\u062a\u0639\u0645\u0627\u0644\u06d4"},{"term":"Social environment","definition_en":"The relationships and norms that govern how people in a classroom treat each other: between teacher and pupils, among pupils, and between the class and any outsider.","definition_ur":"\u0648\u06c1 \u0631\u0634\u062a\u06d2 \u0627\u0648\u0631 \u0627\u0635\u0648\u0644 \u062c\u0648 \u06a9\u0644\u0627\u0633 \u0645\u06cc\u06ba \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0633\u0644\u0648\u06a9 \u06a9\u0627 \u062a\u0639\u06cc\u0646 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba: \u0627\u0633\u062a\u0627\u062f \u0627\u0648\u0631 \u0634\u0627\u06af\u0631\u062f \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646\u060c \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0628\u0627\u06c1\u0645\u060c \u0627\u0648\u0631 \u062c\u0645\u0627\u0639\u062a \u0627\u0648\u0631 \u06a9\u0633\u06cc \u0628\u06cc\u0631\u0648\u0646\u06cc \u0634\u062e\u0635 \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646\u06d4"},{"term":"Classroom observation","definition_en":"The structured act of watching a classroom with a specific focus, recording what is seen in a consistent format, and keeping a clear line between what was observed and what is inferred.","definition_ur":"\u06a9\u0644\u0627\u0633 \u06a9\u06cc \u0628\u0627\u0642\u0627\u0639\u062f\u06c1 \u0646\u06af\u0631\u0627\u0646\u06cc \u062c\u0633 \u0645\u06cc\u06ba \u0645\u062e\u0635\u0648\u0635 \u062a\u0648\u062c\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u0634\u0627\u06c1\u062f\u06c1 \u06a9\u06cc\u0627 \u062c\u0627\u0626\u06d2\u060c \u062f\u06cc\u06a9\u06be\u06cc \u06af\u06cc\u06cc \u0686\u06cc\u0632\u0648\u06ba \u06a9\u0648 \u0628\u0627\u0627\u0635\u0648\u0644 \u0634\u06a9\u0644 \u0645\u06cc\u06ba \u0631\u06cc\u06a9\u0627\u0631\u0688 \u06a9\u06cc\u0627 \u062c\u0627\u0626\u06d2\u060c \u0627\u0648\u0631 \u0645\u0634\u0627\u06c1\u062f\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u0633\u06d2 \u0646\u06a9\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u062a\u06cc\u062c\u06d2 \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0648\u0627\u0636\u062d \u062d\u062f \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u06cc \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Well-managed classroom","definition_en":"A classroom marked by practised routines, high intellectual demand, teacher withitness, and a physical and social environment that supports the intended learning.","definition_ur":"\u0627\u06cc\u0633\u06cc \u06a9\u0644\u0627\u0633 \u062c\u0633 \u06a9\u06cc \u0646\u0634\u0627\u0646\u062f\u06c1\u06cc \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06cc \u062e\u0635\u0648\u0635\u06cc\u0627\u062a \u06cc\u06c1 \u06c1\u06cc\u06ba: \u067e\u0631\u06a9\u06be\u06cc \u06af\u0626\u06cc \u0645\u0634\u0642\u06cc\u06ba\u060c \u0627\u062f\u0631\u06a9\u06cc \u0627\u0639\u0644\u06cc \u0633\u0637\u062d \u06a9\u0627 \u062a\u0642\u0627\u0636\u06c1\u060c \u0627\u0633\u062a\u0627\u062f \u06a9\u06cc \u0686\u0648\u06a9\u0633\u06cc\u060c \u0627\u0648\u0631 \u0627\u06cc\u0633\u0627 \u0645\u0627\u062f\u06cc \u0627\u0648\u0631 \u0645\u0639\u0627\u0634\u0631\u062a\u06cc \u0645\u0627\u062d\u0648\u0644 \u062c\u0633 \u0633\u06d2 \u0645\u0637\u0644\u0648\u0628\u06c1 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0648 \u0645\u062f\u062f \u0645\u0644\u06d2\u06d4"},{"term":"Learning resources","definition_en":"Anything in a classroom a pupil can use to support learning: textbooks, exercise books, the blackboard, posters, real objects, the floor, the wall, and other pupils.","definition_ur":"\u06a9\u0644\u0627\u0633 \u0645\u06cc\u06ba \u0645\u0648\u062c\u0648\u062f \u0648\u06c1 \u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u0686\u06cc\u0632 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631 \u0633\u06a9\u06d2: \u062f\u0631\u0633\u06cc \u06a9\u062a\u0627\u0628\u06cc\u06ba\u060c \u0645\u0634\u0642\u06cc\u06ba\u060c \u0628\u0648\u0631\u0688\u060c \u067e\u0648\u0633\u0679\u0631\u060c \u062d\u0642\u06cc\u0642\u06cc \u0627\u0634\u06cc\u0627\u0621\u060c \u0641\u0631\u0634\u060c \u062f\u06cc\u0648\u0627\u0631\u060c \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06d2 \u0634\u0627\u06af\u0631\u062f\u06d4"},{"term":"Classroom challenges","definition_en":"The recurring frictions that make classroom management harder than textbook routines suggest, including multigrade or overcrowded rooms, resource scarcity, diverse pupil preparation, and unpredictable events.","definition_ur":"\u0648\u06c1 \u0628\u0627\u0631 \u0628\u0627\u0631 \u0622\u0646\u06d2 \u0648\u0627\u0644\u06cc \u0645\u0634\u06a9\u0644\u0627\u062a \u062c\u0648 \u06a9\u0644\u0627\u0633 \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0648 \u06a9\u062a\u0627\u0628\u06cc \u06c1\u062f\u0627\u06cc\u0627\u062a \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0634\u06a9\u0644 \u0628\u0646\u0627\u062a\u06cc \u06c1\u06cc\u06ba\u060c \u062c\u0646 \u0645\u06cc\u06ba \u0645\u0644\u0679\u06cc \u06af\u0631\u06cc\u0688 \u06cc\u0627 \u0628\u06be\u0631\u06d2 \u06c1\u0648\u0626\u06d2 \u06a9\u0645\u0631\u06d2\u060c \u0648\u0633\u0627\u0626\u0644 \u06a9\u06cc \u06a9\u0645\u06cc\u060c \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06cc \u0645\u062a\u0646\u0648\u0639 \u062a\u06cc\u0627\u0631\u06cc\u060c \u0627\u0648\u0631 \u063a\u06cc\u0631 \u0645\u062a\u0648\u0642\u0639 \u0648\u0627\u0642\u0639\u0627\u062a \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u06d4"},{"term":"Thinking","definition_en":"The set of mental functions - remembering, imagining, believing, deciding and reasoning - through which a person takes in information and works on it.","definition_ur":"\u0630\u06c1\u0646\u06cc \u0627\u0641\u0639\u0627\u0644 \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 - \u06cc\u0627\u062f \u0631\u06a9\u06be\u0646\u0627\u060c \u062a\u0635\u0648\u0631 \u06a9\u0631\u0646\u0627\u060c \u06cc\u0642\u06cc\u0646 \u06a9\u0631\u0646\u0627\u060c \u0641\u06cc\u0635\u0644\u06c1 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u06a9\u0631\u0646\u0627 - \u062c\u0633 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u0627\u0646\u0633\u0627\u0646 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062d\u0627\u0635\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0646 \u067e\u0631 \u06a9\u0627\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Egocentrism","definition_en":"The habit of seeing everything from your own position and assuming your view is the natural one - a common barrier to critical thinking.","definition_ur":"\u0627\u067e\u0646\u06cc \u062c\u06af\u06c1 \u0633\u06d2 \u06c1\u0631 \u0686\u06cc\u0632 \u062f\u06cc\u06a9\u06be\u0646\u06d2 \u0627\u0648\u0631 \u0627\u067e\u0646\u06cc \u0631\u0627\u0626\u06d2 \u06a9\u0648 \u0641\u0637\u0631\u06cc \u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06cc \u0639\u0627\u062f\u062a - \u062a\u0646\u0642\u06cc\u062f\u06cc \u0633\u0648\u0686 \u0645\u06cc\u06ba \u0631\u06a9\u0627\u0648\u0679 \u06a9\u0627 \u0627\u06cc\u06a9 \u0639\u0627\u0645 \u0633\u0628\u0628\u06d4"},{"term":"Group conformity","definition_en":"The pressure to think along with those around you, accepting the group\'s view without examining it - a common barrier to critical thinking.","definition_ur":"\u0627\u067e\u0646\u06d2 \u0627\u0631\u062f \u06af\u0631\u062f \u06a9\u06d2 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0633\u0648\u0686\u0646\u06d2 \u06a9\u0627 \u062f\u0628\u0627\u0624\u060c \u06af\u0631\u0648\u06c1 \u06a9\u06cc \u0631\u0627\u0626\u06d2 \u06a9\u0648 \u062c\u0627\u0646\u0686\u06d2 \u0628\u063a\u06cc\u0631 \u0642\u0628\u0648\u0644 \u06a9\u0631\u0646\u0627 - \u062a\u0646\u0642\u06cc\u062f\u06cc \u0633\u0648\u0686 \u0645\u06cc\u06ba \u0631\u06a9\u0627\u0648\u0679 \u06a9\u0627 \u0627\u06cc\u06a9 \u0639\u0627\u0645 \u0633\u0628\u0628\u06d4"},{"term":"Statement","definition_en":"A sentence that claims something is or is not the case - something that can, in principle, be true or false.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0648 \u062f\u0639\u0648\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0686\u06cc\u0632 \u06c1\u06d2 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba \u06c1\u06d2 - \u0627\u06cc\u0633\u06cc \u0686\u06cc\u0632 \u062c\u0648 \u0627\u0635\u0648\u0644 \u0637\u0648\u0631 \u067e\u0631 \u062f\u0631\u0633\u062a \u06cc\u0627 \u063a\u0644\u0637 \u06c1\u0648 \u0633\u06a9\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Claim","definition_en":"A statement put forward as true, often in the face of possible disagreement - a statement that needs support.","definition_ur":"\u0627\u06cc\u06a9 \u0628\u06cc\u0627\u0646 \u062c\u0648 \u062f\u0631\u0633\u062a \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u067e\u06cc\u0634 \u06a9\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u060c \u0627\u06a9\u062b\u0631 \u0645\u0645\u06a9\u0646\u06c1 \u0627\u062e\u062a\u0644\u0627\u0641 \u06a9\u06d2 \u0628\u0627\u0648\u062c\u0648\u062f - \u0627\u06cc\u06a9 \u0628\u06cc\u0627\u0646 \u062c\u0633 \u06a9\u0648 \u0633\u067e\u0648\u0631\u0679 \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Issue","definition_en":"A question that invites more than one reasonable answer - something people can disagree about and that needs reasoning rather than a single factual lookup.","definition_ur":"\u0627\u06cc\u06a9 \u0633\u0648\u0627\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0639\u0642\u0648\u0644 \u062c\u0648\u0627\u0628 \u0645\u0645\u06a9\u0646 \u06c1\u0648\u06ba - \u0627\u06cc\u0633\u06cc \u0686\u06cc\u0632 \u062c\u0633 \u067e\u0631 \u0644\u0648\u06af \u0627\u062e\u062a\u0644\u0627\u0641 \u06a9\u0631 \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u062c\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0635\u0631\u0641 \u0627\u06cc\u06a9 \u062d\u0642\u06cc\u0642\u062a \u062a\u0644\u0627\u0634 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0627\u0633\u062a\u062f\u0644\u0627\u0644 \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u06d4"},{"term":"Argument","definition_en":"A claim plus at least one reason offered to support it - the claim is the conclusion and the reasons are the premises. In critical thinking this is not a quarrel but a supported case.","definition_ur":"\u0627\u06cc\u06a9 \u062f\u0639\u0648\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u0645 \u0627\u0632 \u06a9\u0645 \u0627\u06cc\u06a9 \u0648\u062c\u0648\u06c1\u0627\u062a \u0627\u0633 \u06a9\u06cc \u062d\u0645\u0627\u06cc\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u067e\u06cc\u0634 \u06a9\u06cc \u06af\u0626\u06cc - \u062f\u0639\u0648\u06cc \u0646\u062a\u06cc\u062c\u06c1 \u06c1\u06d2 \u0627\u0648\u0631 \u0648\u062c\u0648\u06c1\u0627\u062a \u0645\u0642\u062f\u0645\u0627\u062a\u06d4 \u062a\u0646\u0642\u06cc\u062f\u06cc \u0633\u0648\u0686 \u0645\u06cc\u06ba \u06cc\u06c1 \u062c\u06be\u06af\u0691\u0627 \u0646\u06c1\u06cc\u06ba \u0628\u0644\u06a9\u06c1 \u0627\u06cc\u06a9 \u0645\u0639\u0627\u0648\u0646 \u0645\u0642\u062f\u0645\u06c1 \u06c1\u06d2\u06d4"},{"term":"Curriculum","definition_en":"The teacher\'s answer to four questions: what to teach, in what order, at what pace, and for whom. In this course each of these is treated as a management act that shapes the classroom before the lesson begins.","definition_ur":"\u0627\u0633\u062a\u0627\u062f \u06a9\u06d2 \u0686\u0627\u0631 \u0633\u0648\u0627\u0644\u0648\u06ba \u06a9\u06d2 \u062c\u0648\u0627\u0628\u0627\u062a: \u06a9\u06cc\u0627 \u067e\u0691\u06be\u0627\u0646\u0627 \u06c1\u06d2\u060c \u06a9\u0633 \u062a\u0631\u062a\u06cc\u0628 \u0645\u06cc\u06ba\u060c \u06a9\u0633 \u0631\u0641\u062a\u0627\u0631 \u0633\u06d2\u060c \u0627\u0648\u0631 \u06a9\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4 \u0627\u0633 \u06a9\u0648\u0631\u0633 \u0645\u06cc\u06ba \u0627\u0646 \u0645\u06cc\u06ba \u0633\u06d2 \u06c1\u0631 \u0627\u06cc\u06a9 \u06a9\u0648 \u0627\u06cc\u06a9 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0639\u0645\u0644 \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0644\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u0633\u0628\u0642 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u06c1\u06cc \u06a9\u0644\u0627\u0633 \u06a9\u06cc \u0634\u06a9\u0644 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Lesson planning","definition_en":"The stage in which the teacher decides the learning target, the activities, the materials, and the time each part of the lesson will take. The management decision at this stage is clarity of target.","definition_ur":"\u0648\u06c1 \u0645\u0631\u062d\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0627\u062f \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u0645\u0642\u0635\u062f\u060c \u0633\u0631\u06af\u0631\u0645\u06cc\u0627\u06ba\u060c \u0645\u0648\u0627\u062f\u060c \u0627\u0648\u0631 \u0633\u0628\u0642 \u06a9\u06d2 \u06c1\u0631 \u062d\u0635\u06d2 \u06a9\u0627 \u0648\u0642\u062a \u0637\u06d2 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0645\u0631\u062d\u0644\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u0645\u0642\u0635\u062f \u06a9\u06cc \u0648\u0636\u0627\u062d\u062a \u06c1\u06d2\u06d4"},{"term":"Motivation","definition_en":"The stage in which the teacher creates the want to learn before the teaching begins. The management decision at this stage is relevance: pupils who can see why the lesson matters to them are easier to teach.","definition_ur":"\u0648\u06c1 \u0645\u0631\u062d\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0627\u062f \u062a\u062f\u0631\u06cc\u0633 \u0633\u06d2 \u067e\u06c1\u0644\u06d2 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u06cc \u062e\u0648\u0627\u06c1\u0634 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u0645\u0631\u062d\u0644\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u0645\u0637\u0627\u0628\u0642\u062a \u06c1\u06d2: \u0648\u06c1 \u0634\u0627\u06af\u0631\u062f \u062c\u0648 \u062f\u06cc\u06a9\u06be \u0633\u06a9\u062a\u06d2 \u06c1\u06cc\u06ba \u06a9\u06c1 \u0633\u0628\u0642 \u0627\u0646 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06cc\u0648\u06ba \u0627\u06c1\u0645 \u06c1\u06d2\u060c \u0627\u0646 \u06a9\u06cc \u062a\u062f\u0631\u06cc\u0633 \u0622\u0633\u0627\u0646 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Assessment","definition_en":"The stage in which the teacher checks whether the learning target has been met. The management decision at this stage is evidence: a teacher who ends the lesson without checking is managing on hope.","definition_ur":"\u0648\u06c1 \u0645\u0631\u062d\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0633\u062a\u0627\u062f \u06cc\u06c1 \u062f\u06cc\u06a9\u06be\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u0645\u0642\u0635\u062f \u067e\u0648\u0631\u0627 \u06c1\u0648\u0627 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba\u06d4 \u0627\u0633 \u0645\u0631\u062d\u0644\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u062b\u0628\u0648\u062a \u06c1\u06d2: \u062c\u0648 \u0627\u0633\u062a\u0627\u062f \u0628\u063a\u06cc\u0631 \u062c\u0627\u0646\u0686\u06d2 \u0633\u0628\u0642 \u062e\u062a\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u0648\u06c1 \u0627\u0645\u06cc\u062f \u067e\u0631 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0631 \u0631\u06c1\u0627 \u06c1\u06d2\u06d4"},{"term":"Differentiation","definition_en":"Adjusting the content, the process, or the product of a lesson so that every pupil works at the edge of their current ability while reaching the same target. It does not mean making some children do easier work.","definition_ur":"\u0633\u0628\u0642 \u06a9\u06d2 \u0645\u0648\u0627\u062f\u060c \u0639\u0645\u0644\u060c \u06cc\u0627 \u0646\u062a\u06cc\u062c\u06d2 \u06a9\u0648 \u0627\u0633 \u0637\u0631\u062d \u0627\u06cc\u0688\u062c\u0633\u0679 \u06a9\u0631\u0646\u0627 \u06a9\u06c1 \u06c1\u0631 \u0634\u0627\u06af\u0631\u062f \u0627\u067e\u0646\u06cc \u0645\u0648\u062c\u0648\u062f\u0627 \u0635\u0644\u0627\u062d\u06cc\u062a \u06a9\u06cc \u062d\u062f \u062a\u06a9 \u06a9\u0627\u0645 \u06a9\u0631\u06d2 \u0627\u0648\u0631 \u0633\u0627\u062a\u06be \u06c1\u06cc \u0627\u06cc\u06a9 \u062c\u06cc\u0633\u06d2 \u0645\u0642\u0635\u062f \u06a9\u0648 \u067e\u06c1\u0646\u0686\u06d2\u06d4 \u0627\u0633 \u0633\u06d2 \u0645\u0631\u0627\u062f \u06cc\u06c1 \u0646\u06c1\u06cc\u06ba \u06a9\u06c1 \u06a9\u0686\u06be \u0628\u0686\u0648\u06ba \u06a9\u0648 \u0622\u0633\u0627\u0646 \u06a9\u0627\u0645 \u062f\u06cc\u0627 \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Multigrade classroom","definition_en":"A classroom in which a single teacher is responsible for pupils of two or more grade levels at the same time, in the same room. It requires management tactics, such as anchor activities and peer tutoring, that a single-grade classroom does not.","definition_ur":"\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u062a\u0627\u062f \u0627\u06cc\u06a9 \u06c1\u06cc \u0648\u0642\u062a \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06c1\u06cc \u06a9\u0645\u0631\u06d2 \u0645\u06cc\u06ba \u062f\u0648 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u062c\u0627\u062a \u06a9\u06d2 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u0630\u0645\u06c1 \u062f\u0627\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u062d\u06a9\u0645\u062a \u0639\u0645\u0644\u06cc \u062f\u0631\u06a9\u0627\u0631 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u0644\u0646\u06af\u0631 \u0633\u0631\u06af\u0631\u0645\u06cc\u0627\u06ba \u0627\u0648\u0631 \u06c1\u0645 \u0639\u0645\u0631 \u062a\u062f\u0631\u06cc\u0633\u060c \u062c\u0648 \u0648\u0627\u062d\u062f \u062f\u0631\u062c\u06d2 \u06a9\u06d2 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u0645\u06cc\u06ba \u0646\u06c1\u06cc\u06ba \u0686\u0627\u06c1\u06cc\u06ba\u06d4"},{"term":"Overcrowded classroom","definition_en":"A classroom in which the number of pupils far exceeds the room\'s designed capacity. The management problem is not just space but the near-impossibility of individual attention at that scale.","definition_ur":"\u0627\u06cc\u0633\u0627 \u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06cc \u062a\u0639\u062f\u0627\u062f \u06a9\u0645\u0631\u06d2 \u06a9\u06cc \u0688\u06cc\u0632\u0627\u0626\u0646 \u0634\u062f\u06c1 \u06af\u0646\u062c\u0627\u0626\u0634 \u0633\u06d2 \u0628\u06c1\u062a \u0632\u06cc\u0627\u062f\u06c1 \u06c1\u0648\u06d4 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u0645\u0633\u0626\u0644\u06c1 \u0635\u0631\u0641 \u062c\u06af\u06c1 \u0646\u06c1\u06cc\u06ba \u0628\u0644\u06a9\u06c1 \u0627\u0633 \u067e\u06cc\u0645\u0627\u0646\u06d2 \u067e\u0631 \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u062a\u0648\u062c\u06c1 \u062f\u06cc\u0646\u06d2 \u06a9\u06cc \u062a\u0642\u0631\u06cc\u0628\u0627\u064b \u0646\u0627\u0645\u0645\u06a9\u0646\u06cc\u062a \u06c1\u06d2\u06d4"},{"term":"Anchor activity","definition_en":"A task that one group of pupils can do independently while the teacher works with another group. A good anchor activity is self-checking, connected to the current topic, and familiar enough to start without the teacher.","definition_ur":"\u0627\u06cc\u0633\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc \u062c\u0648 \u0627\u06cc\u06a9 \u06af\u0631\u0648\u06c1 \u0622\u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Peer tutoring","definition_en":"A structured arrangement in which a pupil who has mastered an explanation teaches it to a peer. It must be structured - the tutor needs a clear role, the tutee a clear task, and the teacher must check that the explanation is correct.","definition_ur":"\u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u0627\u0646\u062a\u0638\u0627\u0645 \u062c\u0633 \u0645\u06cc\u06ba \u0648\u06c1 \u0634\u0627\u06af\u0631\u062f \u062c\u0633 \u0646\u06d2 \u06a9\u0648\u0626\u06cc \u0648\u0636\u0627\u062d\u062a \u0633\u06cc\u06a9\u06be \u0644\u06cc \u06c1\u06d2\u060c \u0627\u0633\u06d2 \u0627\u067e\u0646\u06d2 \u06c1\u0645 \u0639\u0645\u0631 \u06a9\u0648 \u0633\u06a9\u06be\u0627\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u0633\u06d2 \u0645\u0646\u0638\u0645 \u06c1\u0648\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2 - \u0627\u062a\u062f\u0631\u06cc\u0633 \u06a9\u0648 \u06a9\u0648\u0626\u06cc \u0648\u0627\u0636\u062d \u06a9\u0631\u062f\u0627\u0631 \u0686\u0627\u06c1\u06cc\u06d2\u060c \u0645\u062a\u0631\u0628\u06cc\u0679 \u06a9\u0648 \u06a9\u0648\u0626\u06cc \u0648\u0627\u0636\u062d \u06a9\u0627\u0645 \u0686\u0627\u06c1\u06cc\u06d2\u060c \u0627\u0648\u0631 \u0627\u0633\u062a\u0627\u062f \u06a9\u0648 \u06cc\u06c1 \u062c\u0627\u0646\u0686\u0646\u0627 \u0686\u0627\u06c1\u06cc\u06d2 \u06a9\u06c1 \u0648\u0636\u0627\u062d\u062a \u062f\u0631\u0633\u062a \u06c1\u06d2\u06d4"},{"term":"Routine","definition_en":"A repeated way of doing something that pupils learn to do without being told each time. A routine that has been practised until it is automatic is one of the most powerful time-management tools a teacher has.","definition_ur":"\u06a9\u0633\u06cc \u06a9\u0627\u0645 \u06a9\u0648 \u0628\u0627\u0631 \u0628\u0627\u0631 \u06a9\u0631\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u0633\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f \u0628\u063a\u06cc\u0631 \u0628\u062a\u0627\u0626\u06d2 \u0633\u06cc\u06a9\u06be \u062c\u0627\u0626\u06cc\u06ba\u06d4 \u0627\u06cc\u0633\u0627 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0627\u062a\u0646\u0627 \u0645\u0634\u0642 \u0634\u062f\u06c1 \u06c1\u0648 \u06a9\u06d2 \u062e\u0648\u062f\u06a9\u0627\u0631 \u06c1\u0648 \u062c\u0627\u0626\u06d2\u060c \u0627\u0633\u062a\u0627\u062f \u06a9\u06d2 \u067e\u0627\u0633 \u0648\u0642\u062a \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u0627 \u0633\u0628 \u0633\u06d2 \u0637\u0627\u0642\u062a\u0648\u0631 \u0622\u0644\u06c1 \u06c1\u06d2\u06d4"},{"term":"Structure","definition_en":"The framework that holds routines: the timetable, the seating arrangement, the way the room is organised for group work. A structure without routines is just furniture; routines without a structure have nowhere to live.","definition_ur":"\u0648\u06c1 \u0688\u06be\u0627\u0646\u0686\u06c1 \u062c\u0648 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u06a9\u0648 \u0627\u0679\u06be\u0627\u0626\u06d2 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2: \u0679\u0627\u0626\u0645 \u0679\u06cc\u0628\u0644\u060c \u0646\u0634\u0633\u062a\u0648\u06ba \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u060c \u06cc\u0627 \u06af\u0631\u0648\u06c1 \u06a9\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u0645\u0631\u06d2 \u06a9\u0627 \u0627\u0646\u062a\u0638\u0627\u0645\u06d4 \u062f\u0633\u062a\u0648\u0631 \u0639\u0645\u0644 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0688\u06be\u0627\u0646\u0688\u06c1 \u0635\u0631\u0641 \u0641\u0631\u0646\u06cc\u0686\u0631 \u06c1\u06d2\u061b \u0688\u06be\u0627\u0646\u0686\u06d2 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u06a9\u0648 \u0631\u06c1\u0646\u06d2 \u06a9\u06cc \u062c\u06af\u06c1 \u0646\u06c1\u06cc\u06ba \u0645\u0644\u062a\u06cc\u06d4"},{"term":"Procedure","definition_en":"A step-by-step sequence for a specific task: how to sharpen a pencil, how to line up, how to hand in homework. A procedure is taught once and followed many times.","definition_ur":"\u06a9\u0633\u06cc \u0645\u062e\u0635\u0648\u0635 \u06a9\u0627\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0642\u062f\u0645 \u0628\u06c1 \u0642\u062f\u0645 \u062a\u0631\u062a\u06cc\u0628: \u067e\u0646\u0633\u0644 \u06a9\u06cc\u0633\u06d2 \u0686\u06be\u06cc\u0646\u06cc \u062c\u0627\u0626\u06d2\u060c \u0642\u0637\u0627\u0631 \u06a9\u06cc\u0633\u06d2 \u0628\u0646\u0627\u0626\u06cc \u062c\u0627\u0626\u06d2\u060c \u06c1\u0645 \u0648\u0631\u06a9 \u06a9\u06cc\u0633\u06d2 \u062c\u0645\u0639 \u06a9\u0631\u0627\u06cc\u0627 \u062c\u0627\u0626\u06d2\u06d4 \u0627\u06cc\u06a9 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631 \u0627\u06cc\u06a9 \u0628\u0627\u0631 \u0633\u06a9\u06be\u0627\u06cc\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0628\u0627\u0631 \u0628\u0627\u0631 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Rule","definition_en":"A statement of what is allowed or expected in a classroom. A rule sets a boundary; a routine removes the need to enforce that boundary by building the behaviour behind it.","definition_ur":"\u06a9\u0644\u0627\u0633 \u0645\u06cc\u06ba \u0627\u062c\u0627\u0632\u062a \u06cc\u0627 \u062a\u0648\u0642\u0639 \u06a9\u0627 \u0628\u06cc\u0627\u0646\u06d4 \u0627\u06cc\u06a9 \u0627\u0635\u0648\u0644 \u062d\u062f \u0642\u0627\u0626\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u061b \u0627\u06cc\u06a9 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u0627\u0633 \u062d\u062f \u06a9\u0627 \u0646\u0641\u0627\u0630 \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u0636\u0631\u0648\u0631\u062a \u062e\u062a\u0645 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06d2 \u067e\u06cc\u0686\u06be\u06d2 \u0631\u0648\u06cc\u06c1 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Anchor routine","definition_en":"The routine a group of pupils follows while the teacher works with another group. A good anchor routine is self-checking, connected to the current topic, and familiar enough that the teacher is not interrupted.","definition_ur":"\u0648\u06c1 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0627\u06cc\u06a9 \u06af\u0631\u0648\u06c1 \u0627\u0633\u062a\u0627\u062f \u062f\u0648\u0633\u0631\u06d2 \u06af\u0631\u0648\u06c1 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u0627\u0645 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4 \u0627\u06cc\u06a9 \u0627\u0686\u06be\u0627 \u0644\u0646\u06af\u0631 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062e\u0648\u062f \u062c\u0627\u0646\u0686 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u0645\u0648\u062c\u0648\u062f\u06c1 \u0645\u0648\u0636\u0648\u0639 \u0633\u06d2 \u062c\u0691\u0627 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0627\u062a\u0646\u0627 \u0645\u0627\u0646\u0648\u0633 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u0627\u0633\u062a\u0627\u062f \u0645\u06cc\u06ba \u0645\u062f\u062f \u0646\u06c1\u06cc\u06ba \u0645\u0627\u0646\u06af\u062a\u06cc\u06d4"},{"term":"Independent-work routine","definition_en":"The routine that governs what pupils do when working alone: how to get materials, how to ask for help without calling out, what to do when finished.","definition_ur":"\u0648\u06c1 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u06d2 \u0622\u0632\u0627\u062f \u06a9\u0627\u0645 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u0644\u0627\u06af\u0648 \u06c1\u0648\u062a\u0627 \u06c1\u06d2: \u0645\u0648\u0627\u062f \u06a9\u06cc\u0633\u06d2 \u062d\u0627\u0635\u0644 \u06a9\u0631\u06cc\u06ba\u060c \u0628\u0646\u0627 \u0686\u06cc\u062e\u06d2 \u0645\u062f\u062f \u06a9\u06cc\u0633\u06d2 \u0645\u0627\u0646\u06af\u06cc\u06ba\u060c \u062e\u062a\u0645 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u06a9\u06cc\u0627 \u06a9\u0631\u06cc\u06ba\u06d4"},{"term":"Checking routine","definition_en":"A routine that governs how pupils get feedback without queuing for the teacher: self-checking, peer-checking, or traffic-light cards.","definition_ur":"\u0627\u06cc\u0633\u0627 \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u062c\u0648 \u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0648 \u0627\u0633\u062a\u0627\u062f \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0631 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u0631\u0627\u0626\u06d2 \u062d\u0627\u0635\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u0628\u062a\u0627\u062a\u0627 \u06c1\u06d2: \u062e\u0648\u062f \u062c\u0627\u0646\u0686\u060c \u06c1\u0645 \u0639\u0645\u0631 \u062c\u0627\u0646\u0686\u060c \u06cc\u0627 \u0679\u0631\u06cc\u0641\u06a9 \u0644\u0627\u0626\u0679 \u06a9\u0627\u0631\u0688\u0632\u06d4"},{"term":"Collaborative learning","definition_en":"Pupils working together toward a shared goal with individual accountability: every pupil has a role, every role is necessary, and the group cannot succeed unless every member contributes.","definition_ur":"\u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0627 \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u0634\u062a\u0631\u06a9\u06c1 \u06c1\u062f\u0641 \u06a9\u06cc \u0637\u0631\u0641 \u0645\u0644 \u06a9\u0631 \u06a9\u0627\u0645 \u06a9\u0631\u0646\u0627: \u06c1\u0631 \u0634\u0627\u06af\u0631\u062f \u06a9\u0627 \u06a9\u0631\u062f\u0627\u0631 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u06c1\u0631 \u06a9\u0631\u062f\u0627\u0631 \u0636\u0631\u0648\u0631\u06cc \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u0627\u0648\u0631 \u06af\u0631\u0648\u06c1 \u0627\u0633 \u0648\u0642\u062a \u06a9\u0627\u0645\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u062c\u0628 \u062a\u06a9 \u06c1\u0631 \u0631\u06a9\u0646 \u062d\u0635\u06c1 \u0646\u06c1 \u0688\u0627\u0644\u06d2\u06d4"},{"term":"Individual accountability","definition_en":"The requirement that every member of a group has a necessary role and that the group cannot succeed unless every member contributes. Without it, group work becomes one pupil doing the work while others watch.","definition_ur":"\u0648\u06c1 \u062a\u0642\u0627\u0636\u06c1 \u06a9\u06c1 \u06af\u0631\u0648\u06c1 \u06a9\u06d2 \u06c1\u0631 \u0631\u06a9\u0646 \u06a9\u0627 \u06a9\u0631\u062f\u0627\u0631 \u0636\u0631\u0648\u0631\u06cc \u06c1\u0648 \u0627\u0648\u0631 \u06af\u0631\u0648\u06c1 \u0627\u0633 \u0648\u0642\u062a \u06a9\u0627\u0645\u06cc\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u062a\u0627 \u062c\u0628 \u062a\u06a9 \u06c1\u0631 \u0631\u06a9\u0646 \u062d\u0635\u06c1 \u0646\u06c1 \u0688\u0627\u0644\u06d2\u06d4 \u0627\u0633 \u06a9\u06d2 \u0628\u063a\u06cc\u0631\u060c \u06af\u0631\u0648\u06c1 \u06a9\u0627\u0645 \u0627\u06cc\u06a9 \u0634\u0627\u06af\u0631\u062f \u06a9\u0627 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u0627 \u062f\u06cc\u06a9\u06be\u0646\u0627 \u0628\u0646 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Co-operative structure","definition_en":"A way of organising pupils so they work in the same space toward a shared task, helping each other as needed. Think-pair-share, round-robin and numbered heads are co-operative structures.","definition_ur":"\u0634\u0627\u06af\u0631\u062f\u0648\u06ba \u06a9\u0648 \u0645\u0646\u0638\u0645 \u06a9\u0631\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u0633\u0627 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u06c1 \u0648\u06c1 \u0627\u06cc\u06a9 \u06c1\u06cc \u062c\u06af\u06c1 \u0645\u0634\u062a\u0631\u06a9\u06c1 \u06a9\u0627\u0645 \u06a9\u0631\u0648\u06ba \u0627\u0648\u0631 \u0636\u0631\u0648\u0631\u062a \u067e\u0691\u0646\u06d2 \u067e\u0631 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06cc \u0645\u062f\u062f \u06a9\u0631\u06cc\u06ba\u06d4 \u062a\u06be\u0646\u06a9 \u067e\u0626\u06cc\u0631 \u0634\u06cc\u0626\u0631\u060c \u0631\u0627\u0624\u0646\u0688 \u0631\u0627\u0628\u06cc\u0646 \u0627\u0648\u0631 \u0646\u0645\u0628\u0631\u0688 \u06c1\u06cc\u0688\u0632 \u062a\u0639\u0627\u0648\u0646\u06cc \u0688\u06be\u0627\u0646\u0686\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Community","definition_en":"The set of relationships that surround a classroom: the classroom itself, the school, the parents and families, and the local community. Each circle has a different relationship with the school and a different management demand.","definition_ur":"\u0648\u06c1 \u0631\u0634\u062a\u06d2 \u062c\u0648 \u06a9\u0644\u0627\u0633 \u06a9\u06d2 \u0627\u0631\u062f \u06af\u0631\u062f \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba: \u06a9\u0644\u0627\u0633 \u062e\u0648\u062f\u060c \u0627\u0633\u06a9\u0648\u0644\u060c \u0648\u0627\u0644\u062f\u06cc\u0646 \u0627\u0648\u0631 \u062e\u0627\u0646\u062f\u0627\u0646\u060c \u0627\u0648\u0631 \u0645\u0642\u0627\u0645\u06cc \u0628\u0631\u0627\u062f\u0631\u06cc\u06d4 \u06c1\u0631 \u062d\u0644\u0642\u06d2 \u06a9\u0627 \u0627\u0633\u06a9\u0648\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0645\u062e\u062a\u0644\u0641 \u0631\u0634\u062a\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u0627\u0648\u0631 \u0645\u062e\u062a\u0644\u0641 \u0627\u0646\u062a\u0638\u0627\u0645\u06cc \u062a\u0642\u0627\u0636\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Participation","definition_en":"Being present at a school event or contributing to it. Participation is necessary but not sufficient for genuine community involvement.","definition_ur":"\u0627\u0633\u06a9\u0648\u0644 \u06a9\u06d2 \u06a9\u0633\u06cc \u067e\u0631\u0648\u06af\u0631\u0627\u0645 \u0645\u06cc\u06ba \u0634\u0631\u06a9\u062a \u06a9\u0631\u0646\u0627 \u06cc\u0627 \u0627\u0633 \u0645\u06cc\u06ba \u062d\u0635\u06c1 \u0688\u0627\u0644\u0646\u0627\u06d4 \u0634\u0631\u06a9\u062a \u0636\u0631\u0648\u0631\u06cc \u06c1\u06d2 \u0644\u06cc\u06a9\u0646 \u062d\u0642\u06cc\u0642\u06cc \u0628\u0631\u0627\u062f\u0631\u06cc \u0634\u0645\u0648\u0644\u06cc\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u06cc\u06c1 \u0627\u06a9\u06cc\u0644\u0627 \u06a9\u0627\u0641\u06cc \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Involvement","definition_en":"Having a voice in what happens at a school. Involvement goes beyond participation: a participating parent attends; an involved parent helps decide.","definition_ur":"\u0627\u0633\u06a9\u0648\u0644 \u0645\u06cc\u06ba \u062c\u0648 \u06a9\u0686\u06be \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u0627\u0633 \u0645\u06cc\u06ba \u0627\u067e\u0646\u06cc \u0631\u0627\u0626\u06d2 \u062f\u06cc\u0646\u0627\u06d4 \u0634\u0645\u0648\u0644\u06cc\u062a \u0634\u0631\u06a9\u062a \u0633\u06d2 \u0622\u06af\u06d2 \u0628\u0691\u06be \u06a9\u0631 \u06c1\u06d2: \u0634\u0631\u06cc\u06a9 \u0648\u0627\u0644\u062f\u06cc\u0646 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u061b \u0634\u0627\u0645\u0644 \u0648\u0627\u0644\u062f\u06cc\u0646 \u0641\u06cc\u0635\u0644\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Ethic of care","definition_en":"A set of practices built from attentiveness, responsiveness, competence and mutual respect. An ethic of care is not permissiveness: it includes consequences, but they are restorative rather than punitive.","definition_ur":"\u062a\u0648\u062c\u06c1\u060c \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc\u060c \u0635\u0644\u0627\u062d\u06cc\u062a \u0627\u0648\u0631 \u0628\u0627\u06c1\u0645 \u0627\u062d\u062a\u0631\u0627\u0645 \u0633\u06d2 \u0628\u0646\u06d2 \u0639\u0645\u0644 \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1\u06d4 \u062f\u06cc\u06a9\u06be \u0628\u06be\u0627\u0644 \u06a9\u0627 \u0627\u062e\u0644\u0627\u0642\u06cc\u0627\u062a \u0628\u06d2 \u0642\u06cc\u062f \u067e\u0646 \u0646\u06c1\u06cc\u06ba \u06c1\u06d2: \u0627\u0633 \u0645\u06cc\u06ba \u0646\u062a\u0627\u0626\u062c \u0634\u0627\u0645\u0644 \u06c1\u06cc\u06ba\u060c \u0644\u06cc\u06a9\u0646 \u0648\u06c1 \u0633\u0632\u0627 \u062f\u06cc\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u0628\u062d\u0627\u0644\u06cc \u06a9\u06d2 \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Personal accountability","definition_en":"The willingness to own the consequences of your actions and to make them right. Personal accountability is the internalised version of discipline: discipline is external (the teacher enforces), accountability is internal (the pupil owns).","definition_ur":"\u0627\u067e\u0646\u06d2 \u0627\u0639\u0645\u0627\u0644 \u06a9\u06d2 \u0646\u062a\u0627\u0626\u062c \u0642\u0628\u0648\u0644 \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0627\u0646\u06c1\u06cc\u06ba \u062f\u0631\u0633\u062a \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u062e\u0648\u0627\u06c1\u0634\u06d4 \u0630\u0627\u062a\u06cc \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u0636\u0627\u0628\u0637\u06d2 \u06a9\u0627 \u0627\u0646\u062f\u0631\u0648\u0646\u06cc \u0631\u0648\u067e \u06c1\u06d2: \u0636\u0627\u0628\u0637\u06c1 \u0628\u06cc\u0631\u0648\u0646\u06cc \u06c1\u06d2 (\u0627\u0633\u062a\u0627\u062f \u0646\u0627\u0641\u0630 \u06a9\u0631\u062a\u0627 \u06c1\u06d2)\u060c \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u0627\u0646\u062f\u0631\u0648\u0646\u06cc \u06c1\u06d2 (\u0634\u0627\u06af\u0631\u062f \u0642\u0628\u0648\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2)\u06d4"},{"term":"Restorative consequence","definition_en":"A consequence designed to repair the harm caused by a behaviour and to rebuild the relationship, rather than to punish the person. An apology, a repair, or a service to the class are restorative consequences.","definition_ur":"\u0627\u06cc\u0633\u0627 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0648 \u0631\u0648\u06cc\u06d2 \u06a9\u06cc \u0648\u062c\u06c1 \u0633\u06d2 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0646\u0642\u0635\u0627\u0646 \u06a9\u0648 \u0679\u06be\u06cc\u06a9 \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0631\u0634\u062a\u06d2 \u06a9\u0648 \u0628\u062d\u0627\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0648\u060c \u0634\u062e\u0635 \u06a9\u0648 \u0633\u0632\u0627\u0646\u06c1 \u062f\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0646\u06c1\u06cc\u06ba\u06d4 \u0645\u0639\u0630\u0631\u062a\u060c \u0679\u06be\u06cc\u06a9 \u06a9\u0631\u0646\u0627\u060c \u06cc\u0627 \u06a9\u0644\u0627\u0633 \u06a9\u06cc \u062e\u062f\u0645\u062a \u0628\u062d\u0627\u0644\u06cc \u06a9\u06d2 \u0646\u062a\u0627\u0626\u062c \u06c1\u06cc\u06ba\u06d4"},{"term":"Unexpected-event decision aid","definition_en":"A decision framework for when something unplanned happens: the priority order is safety first, then learning, then relationship.","definition_ur":"\u063a\u06cc\u0631 \u0645\u062a\u0648\u0642\u0639 \u0648\u0627\u0642\u0639\u0627\u062a \u06a9\u06d2 \u0644\u06cc\u06d2 \u0641\u06cc\u0635\u0644\u06d2 \u06a9\u0627 \u0688\u06be\u0627\u0646\u0686\u06c1: \u062a\u0631\u062a\u06cc\u0628 \u06a9\u0627 \u062d\u06a9\u0645 \u067e\u06c1\u0644\u06d2 \u062a\u062d\u0641\u0638\u060c \u067e\u06be\u0631 \u0633\u06cc\u06a9\u06be\u0646\u0627\u060c \u067e\u06be\u0631 \u0631\u0634\u062a\u06c1 \u06c1\u06d2\u06d4"},{"term":"Classroom management plan","definition_en":"The course\'s culminating artefact: a document that states a philosophy of learning, describes curriculum decisions, proposes a routine set, and explains how the plan builds care and accountability, all justified by reference to a described classroom.","definition_ur":"\u06a9\u0648\u0631\u0633 \u06a9\u06cc \u0627\u062e\u062a\u062a\u0627\u0645\u06cc \u062a\u062e\u0644\u06cc\u0642: \u0627\u06cc\u0633\u062a\u0627\u062f \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u062c\u0648 \u0633\u06cc\u06a9\u06be\u0646\u06d2 \u06a9\u0627 \u0641\u0644\u0633\u0641\u06c1 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u060c \u0646\u0635\u0627\u0628\u06cc \u0641\u06cc\u0635\u0644\u06d2 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u060c \u062f\u0633\u062a\u0648\u0631 \u0627\u0644\u0639\u0645\u0644 \u06a9\u0627 \u0645\u062c\u0645\u0648\u0639\u06c1 \u062a\u062c\u0648\u06cc\u0632 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u060c \u0627\u0648\u0631 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u0645\u0646\u0635\u0648\u0628\u06c1 \u062f\u06cc\u06a9\u06be \u0628\u06be\u0627\u0644 \u0627\u0648\u0631 \u062c\u0648\u0627\u0628\u062f\u06c1\u06cc \u06a9\u06cc\u0633\u06d2 \u0628\u0646\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Peer critique","definition_en":"A structured protocol for evaluating a classroom management plan against three criteria: clarity, consistency and coverage. The reviewer names the gap; the author decides how to revise.","definition_ur":"\u06a9\u0644\u0627\u0633 \u0631\u0648\u0645 \u0627\u0646\u062a\u0638\u0627\u0645 \u0645\u0646\u0635\u0648\u0628\u06d2 \u06a9\u0627 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631: \u0648\u0636\u0627\u062d\u062a\u060c \u06c1\u0645 \u0622\u06c1\u0646\u06af\u06cc \u0627\u0648\u0631 \u062a\u062d\u0641\u0638\u06d4 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u0646\u06d2 \u0648\u0627\u0644\u0627 \u06a9\u0645\u06cc \u0628\u062a\u0627\u062a\u0627 \u06c1\u06d2\u061b \u0645\u0635\u062d\u062d \u0641\u06cc\u0635\u0644\u06c1 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u06cc\u0633\u06d2 \u062a\u0631\u0645\u06cc\u0645 \u06a9\u06cc \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Summary and close","definition_en":"The course\'s closing synthesis: a whole-group event in which each trainee states a belief that changed across the course and cites the evidence for the change.","definition_ur":"\u06a9\u0648\u0631\u0633 \u06a9\u06cc \u0627\u062e\u062a\u062a\u0627\u0645\u06cc \u062a\u0631\u06a9\u06cc\u0628: \u0627\u06cc\u06a9 \u067e\u0648\u0631\u06d2 \u06af\u0631\u0648\u06c1 \u06a9\u06cc \u062a\u0642\u0631\u06cc\u0628 \u062c\u0633 \u0645\u06cc\u06ba \u06c1\u0631 \u062a\u0631\u0628\u06cc\u062a \u06cc\u0627\u0641\u062a\u06c1 \u0634\u062e\u0635 \u0627\u06cc\u06a9 \u0639\u0642\u06cc\u062f\u06c1 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0648 \u06a9\u0648\u0631\u0633 \u06a9\u06d2 \u062f\u0648\u0631\u0627\u0646 \u0628\u062f\u0644 \u06af\u06cc\u0627 \u0627\u0648\u0631 \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u062b\u0628\u0648\u062a \u067e\u06cc\u0634 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Vocabulary building","definition_en":"The deliberate process of expanding the words you can use accurately, most effectively through contextual usage rather than memorising word lists.","definition_ur":"\u0627\u0644\u0641\u0627\u0638 \u06a9\u0648 \u062f\u0631\u0633\u062a \u0637\u0631\u06cc\u0642\u06d2 \u0633\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06cc \u0635\u0644\u0627\u062d\u06cc\u062a \u06a9\u0648 \u0628\u0691\u06be\u0627\u0646\u06d2 \u06a9\u0627 \u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u0639\u0645\u0644\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0627\u0644\u0641\u0627\u0638 \u06a9\u0648 \u0633\u06cc\u0627\u0642 \u0648 \u0633\u0628\u0627\u0642 \u0645\u06cc\u06ba \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0627\u0646 \u06a9\u06cc \u0641\u06c1\u0633\u062a \u06cc\u0627\u062f \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0624\u062b\u0631 \u06c1\u06d2\u06d4"},{"term":"Synonym","definition_en":"A word with a similar meaning to another word. Synonyms are not interchangeable: they differ in shade of meaning, register and collocation.","definition_ur":"\u06a9\u0633\u06cc \u062f\u0648\u0633\u0631\u06d2 \u0644\u0641\u0638 \u06a9\u06d2 \u0645\u0634\u062a\u0631\u06a9\u06d2 \u0645\u0639\u0646\u06cc \u0648\u0627\u0644\u0627 \u0644\u0641\u0638\u06d4 \u0645\u062a\u0631\u0627\u062f\u0641\u0627\u062a \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06cc \u062c\u06af\u06c1 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0646\u06c1\u06cc\u06ba \u06c1\u0648 \u0633\u06a9\u062a\u06d2: \u0627\u0646 \u0645\u06cc\u06ba \u0645\u0639\u0646\u06cc \u06a9\u0627 \u062f\u0631\u062c\u06c1\u060c \u0633\u0637\u062d \u0627\u0648\u0631 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Antonym","definition_en":"A word with the opposite meaning of another word. Knowing antonyms helps you understand a word more precisely and gives you tools for contrast in writing.","definition_ur":"\u06a9\u0633\u06cc \u062f\u0648\u0633\u0631\u06d2 \u0644\u0641\u0638 \u06a9\u06d2 \u0645\u062a\u0636\u0627\u062f \u0645\u0639\u0646\u06cc \u0648\u0627\u0644\u0627 \u0644\u0641\u0638\u06d4 \u0645\u062a\u0636\u0627\u062f \u062c\u0627\u0646\u0646\u06d2 \u0633\u06d2 \u0622\u067e \u06a9\u0633\u06cc \u0644\u0641\u0638 \u06a9\u0648 \u0632\u06cc\u0627\u062f\u06c1 \u062f\u0631\u0633\u062a \u0633\u0645\u062c\u06be\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u062a\u062d\u0631\u06cc\u0631 \u0645\u06cc\u06ba \u062a\u0636\u0627\u062f \u06a9\u06d2 \u0644\u06cc\u06d2 \u0648\u0633\u0627\u0626\u0644 \u0645\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Idiomatic expression","definition_en":"A phrase whose meaning cannot be worked out from the individual words. Idioms must be learned as whole units because their meaning is figurative, not literal.","definition_ur":"\u0627\u06cc\u06a9 \u0627\u06cc\u0633\u0627 \u0641\u0642\u0631\u06c1 \u062c\u0633 \u06a9\u0627 \u0645\u0639\u0646\u06cc \u0627\u0646\u0641\u0631\u0627\u062f\u06cc \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u0646\u06c1\u06cc\u06ba \u0633\u0645\u062c\u06be\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627\u06d4 \u0645\u062d\u0627\u0648\u0631\u0648\u06ba \u06a9\u0648 \u0645\u06a9\u0637\u0648\u0631\u0648\u06ba \u06a9\u06d2 \u0637\u0648\u0631 \u067e\u0631 \u0633\u06cc\u06a9\u06be\u0646\u0627 \u0636\u0631\u0648\u0631\u06cc \u06c1\u06d2 \u06a9\u06cc\u0648\u0646\u06a9\u06c1 \u0627\u0646 \u06a9\u06d2 \u0645\u0639\u0627\u0646\u06cc \u0639\u0644\u0627\u0645\u062a\u06cc \u06c1\u0648\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0644\u0641\u0638\u06cc \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Affixation","definition_en":"Adding a prefix (at the beginning) or a suffix (at the end) to a root word to create a new word. The most productive word-formation process in English.","definition_ur":"\u06a9\u0633\u06cc \u0628\u0646\u06cc\u0627\u062f\u06cc \u0644\u0641\u0638 \u0645\u06cc\u06ba \u0633\u0627\u0628\u0642\u06c1 (\u0634\u0631\u0648\u0639 \u0645\u06cc\u06ba) \u06cc\u0627 \u0644\u0627\u062d\u0642\u06c1 (\u0622\u062e\u0631 \u0645\u06cc\u06ba) \u0634\u0627\u0645\u0644 \u06a9\u0631\u06a9\u06d2 \u0646\u06cc\u0627 \u0644\u0641\u0638 \u0628\u0646\u0627\u0646\u0627\u06d4 \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0627\u0644\u0641\u0627\u0638 \u06a9\u06cc \u062a\u0634\u06a9\u06cc\u0644 \u06a9\u0627 \u0633\u0628 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0645\u0624\u062b\u0631 \u0639\u0645\u0644\u06d4"},{"term":"Compounding","definition_en":"Joining two complete words to make a new one. The meaning of the compound is often more than the sum of its parts.","definition_ur":"\u062f\u0648 \u0645\u06a9\u0645\u0644 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0648 \u0645\u0644\u0627\u0646\u06d2 \u0633\u06d2 \u0627\u06cc\u06a9 \u0646\u06cc\u0627 \u0644\u0641\u0638 \u0628\u0646\u0627\u0646\u0627\u06d4 \u0645\u0631\u06a9\u0628 \u0644\u0641\u0638 \u06a9\u0627 \u0645\u0639\u0646\u06cc \u0627\u06a9\u062b\u0631 \u0627\u0633 \u06a9\u06d2 \u062d\u0635\u0648\u06ba \u06a9\u06d2 \u0645\u062c\u0645\u0648\u0639\u06d2 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Clipping","definition_en":"Shortening a longer word to create an informal variant. Common in informal English.","definition_ur":"\u06a9\u0633\u06cc \u0637\u0648\u06cc\u0644 \u0644\u0641\u0638 \u06a9\u0648 \u0686\u06be\u0648\u0679\u0627 \u06a9\u0631\u06a9\u06d2 \u0627\u06cc\u06a9 \u063a\u06cc\u0631 \u0631\u0633\u0645\u06cc \u0635\u0648\u0631\u062a \u0628\u0646\u0627\u0646\u0627\u06d4 \u063a\u06cc\u0631 \u0631\u0633\u0645\u06cc \u0627\u0646\u06af\u0631\u06cc\u0632\u06cc \u0645\u06cc\u06ba \u0639\u0627\u0645 \u06c1\u06d2\u06d4"},{"term":"Back formation","definition_en":"Creating a new word by removing what looks like an affix from an existing word.","definition_ur":"\u06a9\u0633\u06cc \u0645\u0648\u062c\u0648\u062f\u06c1 \u0644\u0641\u0638 \u0633\u06d2 \u0627\u06cc\u06a9 \u0627\u06cc\u0633\u0627 \u062d\u0635\u06c1 \u06c1\u0679\u0627\u0646\u06d2 \u0633\u06d2 \u0646\u06cc\u0627 \u0644\u0641\u0638 \u0628\u0646\u0627\u0646\u0627 \u062c\u0648 \u0644\u0627\u062d\u0642\u06c1 \u06cc\u0627 \u0633\u0627\u0628\u0642\u06c1 \u062f\u06a9\u06be\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Subject-verb agreement","definition_en":"The rule that a verb must match its subject in number: singular subjects take singular verbs, plural subjects take plural verbs.","definition_ur":"\u0648\u06c1 \u0627\u0635\u0648\u0644 \u062c\u0633 \u06a9\u06d2 \u0645\u0637\u0627\u0628\u0642 \u0641\u0639\u0644 \u06a9\u0627 \u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062a\u0639\u062f\u0627\u062f \u0645\u06cc\u06ba \u06c1\u0645 \u0622\u06c1\u0646\u06af \u06c1\u0648\u0646\u0627 \u0636\u0631\u0648\u0631\u06cc \u06c1\u06d2: \u0648\u0627\u062d\u062f \u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0648\u0627\u062d\u062f \u0641\u0639\u0644\u060c \u062c\u0645\u0639 \u0641\u0627\u0639\u0644 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u062c\u0645\u0639 \u0641\u0639\u0644\u06d4"},{"term":"Verb tense","definition_en":"The form of a verb that tells the reader when an action happens: past, present or future.","definition_ur":"\u0641\u0639\u0644 \u06a9\u06cc \u0648\u06c1 \u0635\u0648\u0631\u062a \u062c\u0648 \u0642\u0627\u0631\u06cc \u06a9\u0648 \u0628\u062a\u0627\u062a\u06cc \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0639\u0645\u0644 \u06a9\u0628 \u06c1\u0648\u0627: \u0645\u0627\u0636\u06cc\u060c \u062d\u0627\u0644 \u06cc\u0627 \u0645\u0633\u062a\u0642\u0628\u0644\u06d4"},{"term":"Fragment","definition_en":"An incomplete sentence missing a subject, a verb, or both.","definition_ur":"\u0627\u06cc\u06a9 \u0646\u0627\u0645\u06a9\u0645\u0644 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0641\u0627\u0639\u0644\u060c \u0641\u0639\u0644 \u06cc\u0627 \u062f\u0648\u0646\u0648\u06ba \u063a\u0627\u0626\u0628 \u06c1\u0648\u06ba\u06d4"},{"term":"Run-on sentence","definition_en":"Two complete sentences joined without proper punctuation or a conjunction.","definition_ur":"\u062f\u0648 \u0645\u06a9\u0645\u0644 \u062c\u0645\u0644\u0648\u06ba \u06a9\u0648 \u0645\u0646\u0627\u0633\u0628 \u0631\u0645\u0627\u06a9\u0627\u0646 \u06cc\u0627 \u062d\u0631\u0641 \u0639\u0637\u0641 \u06a9\u06d2 \u0628\u063a\u06cc\u0631 \u062c\u0648\u0691\u0646\u06d2 \u0633\u06d2 \u0628\u0646\u0646\u06d2 \u0648\u0627\u0644\u0627 \u062c\u0645\u0644\u06c1\u06d4"},{"term":"Misplaced modifier","definition_en":"A word or phrase that describes another word but is positioned so that it creates confusion about what is being described.","definition_ur":"\u0627\u06cc\u06a9 \u0644\u0641\u0638 \u06cc\u0627 \u0641\u0642\u0631\u06c1 \u062c\u0648 \u06a9\u0633\u06cc \u062f\u0648\u0633\u0631\u06d2 \u0644\u0641\u0638 \u06a9\u06cc \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u0644\u06cc\u06a9\u0646 \u0627\u06cc\u0633\u06cc \u062c\u06af\u06c1 \u0631\u06a9\u06be\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06cc\u06c1 \u0627\u0644\u062c\u06c1\u0627\u0646 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Article","definition_en":"A word that signals whether a noun is specific or general.","definition_ur":"\u0627\u06cc\u06a9 \u0644\u0641\u0638 \u062c\u0648 \u0627\u0633 \u0628\u0627\u062a \u06a9\u06cc \u0646\u0634\u0627\u0646\u062f\u06c1\u06cc \u06a9\u0631\u062a\u0627 \u06c1\u06d2 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0627\u0633\u0645 \u0645\u062e\u0635\u0648\u0635 \u06c1\u06d2 \u06cc\u0627 \u0639\u0627\u0645\u06d4"},{"term":"Word class","definition_en":"The category a word falls into based on its function in a sentence: noun, verb, adjective, adverb, preposition, conjunction, pronoun or article.","definition_ur":"\u0648\u06c1 \u0632\u0645\u0631\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u06a9\u0648\u0626\u06cc \u0644\u0641\u0638 \u062c\u0645\u0644\u06d2 \u0645\u06cc\u06ba \u0627\u067e\u0646\u06d2 \u06a9\u0627\u0645 \u06a9\u06d2 \u0627\u0639\u062a\u0628\u0627\u0631 \u0633\u06d2 \u0622\u062a\u0627 \u06c1\u06d2: \u0627\u0633\u0645\u060c \u0641\u0639\u0644\u060c \u0635\u0641\u062a\u060c \u0638\u0631\u0641\u060c \u062d\u0631\u0641 \u0631\u0628\u0637\u060c \u062d\u0631\u0641 \u0639\u0637\u0641\u060c \u0636\u0645\u06cc\u0631 \u06cc\u0627 \u062d\u0631\u0641 \u062a\u0639\u0631\u06cc\u0641\u06d4"},{"term":"Simple sentence","definition_en":"A sentence with one independent clause.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06c1 \u06c1\u0648\u06d4"},{"term":"Compound sentence","definition_en":"A sentence with two independent clauses joined by a coordinating conjunction.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0648 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06d2 \u062f\u0648 \u062d\u0631\u0641 \u0631\u0628\u0637 \u0633\u06d2 \u062c\u0648\u0691\u06d2 \u06af\u0626\u06d2 \u06c1\u0648\u06ba\u06d4"},{"term":"Complex sentence","definition_en":"A sentence with one independent clause and one or more dependent clauses.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06c1 \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u0648\u0627\u0628\u0633\u062a\u06c1 \u0641\u0642\u0631\u06d2 \u06c1\u0648\u06ba\u06d4"},{"term":"Compound-complex sentence","definition_en":"A sentence with two independent clauses and one or more dependent clauses.","definition_ur":"\u0627\u06cc\u06a9 \u062c\u0645\u0644\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0648 \u0622\u0632\u0627\u062f \u0641\u0642\u0631\u06d2 \u0627\u0648\u0631 \u0627\u06cc\u06a9 \u06cc\u0627 \u0632\u06cc\u0627\u062f\u06c1 \u0648\u0627\u0628\u0633\u062a\u06c1 \u0641\u0642\u0631\u06d2 \u06c1\u0648\u06ba\u06d4"},{"term":"Editing","definition_en":"The process of improving a text at every level by reading, identifying errors, correcting, reading aloud and repeating until the text is clean.","definition_ur":"\u06c1\u0631 \u0633\u0637\u062d \u067e\u0631 \u0645\u062a\u0646 \u06a9\u0648 \u0628\u06c1\u062a\u0631 \u0628\u0646\u0627\u0646\u06d2 \u06a9\u0627 \u0639\u0645\u0644 - \u067e\u0691\u06be \u06a9\u0631\u060c \u063a\u0644\u0637\u06cc\u0648\u06ba \u06a9\u06cc \u0646\u0634\u0627\u0646\u062f\u06c1\u06cc \u06a9\u0631 \u06a9\u06d2\u060c \u062f\u0631\u0633\u062a \u06a9\u0631 \u06a9\u06d2\u060c \u0628\u0644\u0646\u062f \u0622\u0648\u0627\u0632 \u0633\u06d2 \u067e\u0691\u06be \u06a9\u0631 \u0627\u0648\u0631 \u062a\u06a9\u0631\u0627\u0631 \u06a9\u0631 \u06a9\u06d2\u06d4"},{"term":"Pronunciation","definition_en":"The way in which spoken words are sounded. Clear pronunciation supports clear writing.","definition_ur":"\u0628\u0648\u0644\u06d2 \u062c\u0627\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0627\u0644\u0641\u0627\u0638 \u06a9\u06cc \u0622\u0648\u0627\u0632\u06d4 \u0635\u0627\u0641 \u062a\u0644\u0641\u0638 \u0635\u0627\u0641 \u062a\u062d\u0631\u06cc\u0631 \u06a9\u06cc \u062d\u0645\u0627\u06cc\u062a \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Register","definition_en":"The level of formality that a situation demands in language use.","definition_ur":"\u0632\u0628\u0627\u0646 \u06a9\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0627 \u0648\u06c1 \u0633\u0637\u062d \u062c\u0633\u06d2 \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u0645\u06cc\u06ba \u0636\u0631\u0648\u0631\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Collocation","definition_en":"The tendency of certain words to appear together.","definition_ur":"\u0628\u0639\u0636 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0627 \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u0622\u0646\u06d2 \u06a9\u0627 \u0631\u062c\u062d\u0627\u0646\u06d4"},{"term":"Connotation","definition_en":"The feeling or association a word carries beyond its literal meaning.","definition_ur":"\u06a9\u0633\u06cc \u0644\u0641\u0638 \u06a9\u0627 \u0648\u06c1 \u0627\u062d\u0633\u0627\u0633 \u06cc\u0627 \u062a\u0639\u0644\u0642 \u062c\u0648 \u0627\u0633 \u06a9\u06d2 \u0627\u0635\u0644 \u0645\u0639\u0646\u06cc \u0633\u06d2 \u0622\u06af\u06d2 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Communicative grammar","definition_en":"The study of how grammar creates meaning in real communication.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1 \u06a9\u06c1 \u06af\u0631\u0627\u0645\u0631 \u062d\u0642\u06cc\u0642\u06cc \u0631\u0627\u0628\u0637\u06d2 \u0645\u06cc\u06ba \u0645\u0639\u0646\u06cc \u06a9\u06cc\u0633\u06d2 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Word formation","definition_en":"The processes by which new words are built from existing parts.","definition_ur":"\u0648\u06c1 \u0639\u0645\u0644 \u062c\u0633 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u0646\u0626\u06d2 \u0627\u0644\u0641\u0627\u0638 \u0645\u0648\u062c\u0648\u062f\u06c1 \u062d\u0635\u0648\u06ba \u0633\u06d2 \u0628\u0646\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Sentence structure","definition_en":"The way clauses are combined to form sentences.","definition_ur":"\u0648\u06c1 \u0637\u0631\u06cc\u0642\u06c1 \u062c\u0633 \u0633\u06d2 \u062c\u0645\u0644\u0648\u06ba \u06a9\u0648 \u0645\u0644\u06a9\u0631 \u062c\u0645\u0644\u06d2 \u0628\u0646\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Stress","definition_en":"The relative emphasis placed on a syllable within a word.","definition_ur":"\u06a9\u0633\u06cc \u0644\u0641\u0638 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0634\u062f\u0627\u062f \u067e\u0631 \u062f\u06cc \u06af\u0626\u06cc \u0646\u0633\u0628\u06cc \u062a\u0648\u062c\u06c1\u06d4"},{"term":"Intonation","definition_en":"The rise and fall of the voice across a phrase or sentence.","definition_ur":"\u06a9\u0633\u06cc \u062c\u0645\u0644\u06d2 \u06cc\u0627 \u062c\u0645\u0644\u06d2 \u0645\u06cc\u06ba \u0622\u0648\u0627\u0632 \u06a9\u0627 \u0686\u0691\u06be\u0646\u0627 \u0627\u0648\u0631 \u0627\u062a\u0631\u0646\u0627\u06d4"},{"term":"Phoneme","definition_en":"The smallest unit of sound that can change meaning.","definition_ur":"\u0622\u0648\u0627\u0632 \u06a9\u0627 \u0686\u06be\u0648\u0679\u0627 \u062a\u0631\u06cc\u0646 \u06cc\u0648\u0646\u0679 \u062c\u0648 \u0645\u0639\u0646\u06cc \u0628\u062f\u0644 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Minimal pair","definition_en":"A pair of words that differ by only one sound.","definition_ur":"\u062f\u0648 \u0627\u0644\u0641\u0627\u0638 \u06a9\u0627 \u0627\u06cc\u06a9 \u062c\u0648\u0691\u0627 \u062c\u0648 \u0635\u0631\u0641 \u0627\u06cc\u06a9 \u0622\u0648\u0627\u0632 \u0633\u06d2 \u0645\u062e\u062a\u0644\u0641 \u06c1\u0648\u06d4"},{"term":"Purpose","definition_en":"Why a text was written.","definition_ur":"\u0645\u062a\u0646 \u06a9\u06cc\u0648\u06ba \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627\u06d4"},{"term":"Audience","definition_en":"Who the text is written for.","definition_ur":"\u0645\u062a\u0646 \u06a9\u0633 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0644\u06a9\u06be\u0627 \u06af\u06cc\u0627\u06d4"},{"term":"Context","definition_en":"The situation in which the text was produced and is being read.","definition_ur":"\u0648\u06c1 \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u062a\u062d\u0631\u06cc\u0631 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0626\u06cc \u0627\u0648\u0631 \u067e\u0691\u06be\u06cc \u062c\u0627 \u0631\u06c1\u06cc \u06c1\u06d2\u06d4"},{"term":"Tone","definition_en":"The writer\'s attitude toward the subject or the audience.","definition_ur":"\u0645\u0635\u0646\u0641 \u06a9\u0627 \u0645\u0648\u0636\u0648\u0639 \u06cc\u0627 \u0633\u0627\u0645\u0639\u06cc\u0646 \u06a9\u06d2 \u062a\u0639\u0644\u0642 \u06a9\u0627 \u0631\u0648\u06cc\u06c1\u06d4"},{"term":"Bias","definition_en":"A tendency to favour one perspective over others.","definition_ur":"\u0627\u06cc\u06a9 \u0646\u0642\u0637\u06c1 \u0646\u0638\u0631 \u06a9\u0648 \u062f\u0648\u0633\u0631\u06d2 \u067e\u0631 \u062a\u0631\u062c\u06cc\u062d \u062f\u06cc\u0646\u06d2 \u06a9\u0627 \u0631\u062c\u062d\u0627\u0646\u06d4"},{"term":"Stereotype","definition_en":"A fixed, oversimplified belief about a group of people.","definition_ur":"\u06a9\u0633\u06cc \u06af\u0631\u0648\u06c1 \u06a9\u06d2 \u0628\u0627\u0631\u06d2 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0645\u0642\u0631\u0631\u06c1\u060c \u062d\u062f \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0633\u0627\u062f\u06c1 \u0639\u0642\u06cc\u062f\u06c1\u06d4"},{"term":"Assumption","definition_en":"Something the writer takes for granted without stating it explicitly.","definition_ur":"\u0648\u06c1 \u0686\u06cc\u0632 \u062c\u0633\u06d2 \u0645\u0635\u0646\u0641 \u0628\u063a\u06cc\u0631 \u0648\u0627\u0636\u062d \u0637\u0648\u0631 \u067e\u0631 \u0628\u06cc\u0627\u0646 \u06a9\u06cc\u06d2 \u0639\u0627\u0645 \u0633\u0645\u062c\u06be\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Inference","definition_en":"A conclusion the reader draws from evidence in the text.","definition_ur":"\u0648\u06c1 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0648 \u0642\u0627\u0631\u06cc \u0645\u062a\u0646 \u06a9\u06d2 \u0634\u0648\u0627\u06c1\u062f \u0633\u06d2 \u0627\u062e\u0630 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Active listening","definition_en":"Listening with the intention to understand, not just to hear.","definition_ur":"\u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06cc \u0646\u06cc\u062a \u0633\u06d2 \u0633\u0646\u0646\u0627\u060c \u0635\u0631\u0641 \u0633\u0646\u0646\u0627 \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Critical reading","definition_en":"Reading to evaluate a text, not just understand it.","definition_ur":"\u0645\u062a\u0646 \u06a9\u0648 \u0635\u0631\u0641 \u0633\u0645\u062c\u06be\u0646\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06c1 \u062c\u0627\u0626\u0632\u06c1 \u0644\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u067e\u0691\u06be\u0646\u0627\u06d4"},{"term":"Reading strategies","definition_en":"Deliberate approaches to reading that match the reader\'s purpose.","definition_ur":"\u067e\u0691\u06be\u0646\u06d2 \u06a9\u06d2 \u062c\u0627\u0646 \u0628\u0648\u062c\u06be \u06a9\u0631 \u0627\u067e\u0646\u0627\u0626\u06d2 \u06af\u0626\u06d2 \u0637\u0631\u06cc\u0642\u06d2 \u062c\u0648 \u0642\u0627\u0631\u06cc \u06a9\u06d2 \u0645\u0642\u0635\u062f \u0633\u06d2 \u0645\u0645\u0627\u062b\u0644\u062a \u0631\u06a9\u06be\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Skimming","definition_en":"Reading quickly to get the main idea of a text.","definition_ur":"\u0645\u062a\u0646 \u06a9\u0627 \u0628\u0646\u06cc\u0627\u062f\u06cc \u062e\u06cc\u0627\u0644 \u062d\u0627\u0635\u0644 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062c\u0644\u062f\u06cc \u0633\u06d2 \u067e\u0691\u06be\u0646\u0627\u06d4"},{"term":"Scanning","definition_en":"Reading quickly to find specific information.","definition_ur":"\u0645\u062e\u0635\u0648\u0635 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u062a\u0644\u0627\u0634 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062c\u0644\u062f\u06cc \u0633\u06d2 \u067e\u0691\u06be\u0646\u0627\u06d4"},{"term":"SQ4R","definition_en":"A structured reading strategy: survey, question, read, recite, review, reflect.","definition_ur":"\u0627\u06cc\u06a9 \u0645\u0646\u0638\u0645 \u067e\u0691\u06be\u0646\u06d2 \u06a9\u06cc \u062d\u06a9\u0645\u062a \u0639\u0645\u0644\u06cc: \u0633\u0631\u0648\u06d2\u060c \u0633\u0648\u0627\u0644\u060c \u067e\u0691\u06be\u0646\u0627\u060c \u062f\u06c1\u0631\u0627\u0646\u0627\u060c \u062c\u0627\u0626\u0632\u06c1\u060c \u063a\u0648\u0631\u06d4"},{"term":"Note-taking","definition_en":"Recording what you hear or read in a way that helps you remember.","definition_ur":"\u062c\u0648 \u0633\u0646\u06cc\u06ba \u06cc\u0627 \u067e\u0691\u06be\u06cc\u06ba \u0627\u0633\u06d2 \u06cc\u0627\u062f \u0631\u06a9\u06be\u0646\u06d2 \u0645\u06cc\u06ba \u0645\u062f\u062f \u062f\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0631\u06cc\u06a9\u0627\u0631\u0688 \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Inclusive language","definition_en":"Language that avoids stereotypes, assumptions and gendered terms, and addresses everyone on equal terms.","definition_ur":"\u0648\u06c1 \u0632\u0628\u0627\u0646 \u062c\u0648 \u062a\u0635\u0648\u0631\u06cc\u0627\u062a\u060c \u0641\u0631\u0636\u06cc\u0627\u062a \u0627\u0648\u0631 \u0635\u0646\u0641\u06cc \u0627\u0644\u0641\u0627\u0638 \u0633\u06d2 \u067e\u0631\u06c1\u06cc\u0632 \u06a9\u0631\u06d2 \u0627\u0648\u0631 \u06c1\u0631 \u0634\u062e\u0635 \u06a9\u0648 \u0628\u0631\u0627\u0628\u0631\u06cc \u06a9\u06d2 \u0633\u0627\u062a\u06ba \u062e\u0637\u0627\u0628 \u06a9\u0631\u06d2\u06d4"},{"term":"Cross-cultural communication","definition_en":"Communication between people from different cultural backgrounds, requiring adaptation, listening and suspension of judgement.","definition_ur":"\u0645\u062e\u062a\u0644\u0641 \u062b\u0642\u0627\u0641\u062a\u06cc \u067e\u0633 \u0645\u0646\u0638\u0631 \u06a9\u06d2 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u0631\u0627\u0628\u0637\u06c1\u060c \u062c\u0633 \u0645\u06cc\u06ba \u0645\u0648\u0627\u0641\u0642\u062a\u060c \u0633\u0646\u0646\u0627 \u0627\u0648\u0631 \u0631\u0627\u0626\u06d2 \u0645\u0639\u0637\u0644 \u06a9\u0631\u0646\u0627 \u0634\u0627\u0645\u0644 \u06c1\u06d2\u06d4"},{"term":"Public speaking","definition_en":"Speaking to a group with a purpose: to inform, persuade or explain.","definition_ur":"\u06a9\u0633\u06cc \u0645\u0642\u0635\u062f \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06af\u0631\u0648\u06c1 \u0633\u06d2 \u06af\u0641\u062a\u06af\u0648 \u06a9\u0631\u0646\u0627: \u0622\u06af\u0627\u06c1 \u06a9\u0631\u0646\u0627\u060c \u0642\u0627\u0626\u0644 \u06a9\u0631\u0646\u0627 \u06cc\u0627 \u0648\u0636\u0627\u062d\u062a \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Stage fright","definition_en":"The intense fear of speaking in front of others, which can be managed through preparation, rehearsal and breathing techniques.","definition_ur":"\u062f\u0648\u0633\u0631\u06d2 \u0644\u0648\u06af\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u0645\u0646\u06d2 \u0628\u0648\u0644\u0646\u06d2 \u06a9\u0627 \u0634\u062f\u06cc\u062f \u062e\u0648\u0641\u060c \u062c\u0648 \u062a\u06cc\u0627\u0631\u06cc\u060c \u0645\u0634\u0642 \u0627\u0648\u0631 \u0633\u0627\u0646\u0633 \u0644\u06cc\u0646\u06d2 \u06a9\u06cc \u062a\u06a9\u0646\u06cc\u06a9 \u0633\u06d2 \u0642\u0627\u0628\u0648 \u06a9\u06cc\u0627 \u062c\u0627 \u0633\u06a9\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Voice modulation","definition_en":"The deliberate variation of volume, pace and pitch to hold attention and convey meaning.","definition_ur":"\u062a\u0648\u062c\u06c1 \u0627\u06a9\u0679\u06be\u06cc \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0645\u0645\u0646\u06cc \u067e\u06c1\u0646\u0686\u0627\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u0648\u0627\u0632 \u06a9\u0627 \u062d\u062c\u0645\u060c \u0631\u0641\u062a\u0627\u0631 \u0627\u0648\u0631 \u0644\u06c1\u062c\u06d2 \u062c\u0627\u0646 \u0628\u0648\u062c\u06be \u06a9\u0631 \u0628\u062f\u0644\u0646\u0627\u06d4"},{"term":"Presentation skills","definition_en":"The abilities that let you plan and deliver a clear, engaging talk to a group, from defining purpose to handling questions.","definition_ur":"\u0648\u06c1 \u0635\u0644\u0627\u062d\u06cc\u062a\u06cc\u06ba \u062c\u0648 \u0622\u067e \u06a9\u0648 \u0645\u0642\u0635\u062f \u0645\u062a\u0639\u06cc\u0646 \u06a9\u0631\u0646\u06d2 \u0633\u06d2 \u0644\u06d2 \u06a9\u0631 \u0633\u0648\u0627\u0644\u0627\u062a \u06a9\u0648 \u0633\u0646\u0628\u06be\u0627\u0644\u0646\u06d2 \u062a\u06a9 \u06af\u0631\u0648\u06c1 \u06a9\u0648 \u0648\u0627\u0636\u062d \u0627\u0648\u0631 \u062f\u0644\u06a9\u0634 \u06af\u0641\u062a\u06af\u0648 \u067e\u06cc\u0634 \u06a9\u0631\u0646\u06d2 \u062f\u06cc\u062a\u06cc \u06c1\u06cc\u06ba\u06d4"},{"term":"Handling Q&A","definition_en":"Responding to audience questions confidently, including admitting when you do not know the answer and offering to follow up.","definition_ur":"\u0633\u0627\u0645\u0639\u06cc\u0646 \u06a9\u06d2 \u0633\u0648\u0627\u0644\u0627\u062a \u067e\u0631 \u0627\u0639\u062a\u0645\u0627\u062f \u0633\u06d2 \u062c\u0648\u0627\u0628 \u062f\u06cc\u0646\u0627\u060c \u0628\u0634\u0645\u0648\u0644 \u0627\u0633 \u0628\u0627\u062a \u06a9\u06cc \u062a\u0633\u0644\u06cc\u0645 \u06a9\u0631\u0646\u0627 \u06a9\u06c1 \u0622\u067e \u06a9\u0648 \u062c\u0648\u0627\u0628 \u0646\u06c1\u06cc\u06ba \u0645\u0639\u0644\u0648\u0645 \u0627\u0648\u0631 \u0628\u0639\u062f \u0645\u06cc\u06ba \u0628\u062a\u0627\u0646\u06d2 \u06a9\u06cc \u067e\u06cc\u0634\u06a9\u0634 \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Managing time","definition_en":"Planning how long each section of a presentation will take and sticking to the plan so the talk finishes on time.","definition_ur":"\u067e\u06cc\u0634\u06a9\u0634 \u06a9\u06d2 \u06c1\u0631 \u062d\u0635\u06d2 \u06a9\u0627 \u0648\u0642\u062a \u0637\u06d2 \u06a9\u0631\u0646\u0627 \u0627\u0648\u0631 \u0645\u0646\u0635\u0648\u0628\u06d2 \u067e\u0631 \u0642\u0627\u0626\u0645 \u0631\u06c1\u0646\u0627 \u062a\u0627\u06a9\u06c1 \u06af\u0641\u062a\u06af\u0648 \u0648\u0642\u062a \u067e\u0631 \u062e\u062a\u0645 \u06c1\u0648\u06d4"},{"term":"Informal communication","definition_en":"Unplanned, everyday talk that builds professional relationships, such as small talk, networking and staffroom conversation.","definition_ur":"\u063a\u06cc\u0631 \u0645\u0646\u0638\u0645\u060c \u0631\u0648\u0632\u0645\u0631\u06c1 \u06af\u0641\u062a\u06af\u0648 \u062c\u0648 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0631\u0634\u062a\u06d2 \u0628\u0646\u0627\u062a\u06cc \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u06c1\u0644\u06a9\u06cc \u067e\u06be\u0644\u06a9\u06cc \u0628\u0627\u062a \u0686\u06cc\u062a\u060c \u062c\u0627\u0644\u062a \u0627\u0648\u0631 \u0627\u0633\u0627\u062a\u0630\u06c1 \u06a9\u06d2 \u06a9\u0645\u0631\u06d2 \u06a9\u06cc \u06af\u0641\u062a\u06af\u0648\u06d4"},{"term":"Small talk","definition_en":"Brief, light conversation about non-controversial topics, used to build rapport rather than exchange information.","definition_ur":"\u063a\u06cc\u0631 \u0645\u062a\u0646\u0648\u0639 \u0645\u0648\u0636\u0648\u0639\u0627\u062a \u067e\u0631 \u0645\u062e\u062a\u0635\u0631\u060c \u06c1\u0644\u06a9\u06cc \u06af\u0641\u062a\u06af\u0648\u060c \u062c\u0648 \u0645\u0639\u0644\u0648\u0645\u0627\u062a \u06a9\u06d2 \u062a\u0628\u0627\u062f\u0644\u06d2 \u06a9\u06d2 \u0628\u062c\u0627\u0626\u06d2 \u062a\u0639\u0644\u0642 \u0628\u0646\u0627\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Networking","definition_en":"Building and maintaining professional relationships through genuine short exchanges that lead to concrete next steps.","definition_ur":"\u062d\u0642\u06cc\u0642\u06cc \u0645\u062e\u062a\u0635\u0631 \u06af\u0641\u062a\u06af\u0648 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u0631\u0634\u062a\u06d2 \u0628\u0646\u0627\u0646\u0627 \u0627\u0648\u0631 \u0628\u0631\u0642\u0631\u0627\u0631 \u0631\u06a9\u06be\u0646\u0627\u060c \u062c\u0648 \u0645\u0644\u0645\u0648\u0633 \u0627\u06af\u0644\u06d2 \u0642\u062f\u0645\u0648\u06ba \u06a9\u06cc \u0637\u0631\u0641 \u0644\u06d2 \u062c\u0627\u0626\u06d2\u06d4"},{"term":"Turn-taking","definition_en":"The convention by which speakers alternate in a conversation, using cues such as pauses and intonation.","definition_ur":"\u0648\u06c1 \u0627\u0635\u0648\u0644 \u062c\u0633 \u06a9\u06d2 \u062a\u062d\u062a \u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0628\u0627\u0631\u06cc \u0628\u0627\u0631\u06cc \u0628\u0648\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0648\u0642\u0641\u0648\u06ba \u0627\u0648\u0631 \u0644\u06c1\u062c\u06d2 \u06a9\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u062c\u06cc\u0633\u06cc \u0627\u0634\u0627\u0631\u0648\u06ba \u06a9\u06d2 \u0633\u0627\u062a\u06be\u06d4"},{"term":"Conversational repair","definition_en":"What speakers do when something goes wrong in a conversation, such as rephrasing, asking for clarification or checking understanding.","definition_ur":"\u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u06a9\u0686\u06be \u063a\u0644\u0637 \u06c1\u0648\u0646\u06d2 \u067e\u0631 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u0627 \u06a9\u06cc\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u062f\u0648\u0628\u0627\u0631\u06c1 \u0628\u06cc\u0627\u0646 \u06a9\u0631\u0646\u0627\u060c \u0648\u0636\u0627\u062d\u062a \u0645\u0627\u0646\u06af\u0646\u0627 \u06cc\u0627 \u0633\u0645\u062c\u06be \u06a9\u06cc \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u0646\u0627\u06d4"},{"term":"Politeness strategies","definition_en":"Ways speakers protect each other\'s dignity in interaction, such as indirectness, hedging and showing appreciation.","definition_ur":"\u0648\u06c1 \u0637\u0631\u06cc\u0642\u06d2 \u062c\u0646 \u0633\u06d2 \u0628\u0648\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u06af\u0641\u062a\u06af\u0648 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0648\u0642\u0627\u0631 \u06a9\u0627 \u062a\u062d\u0641\u0638 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u062c\u06cc\u0633\u06d2 \u0628\u0627\u0644\u0648\u0627\u0633\u0637\u06c1 \u067e\u0646\u060c \u0627\u062d\u062a\u06cc\u0627\u0637 \u0627\u0648\u0631 \u062a\u0639\u0631\u06cc\u0641 \u062f\u06a9\u06be\u0627\u0646\u0627\u06d4"},{"term":"Business email","definition_en":"A professional writing format used to request, inform, confirm or follow up within or between organisations, following a clear structure: subject line, salutation, opening, body, closing and signature.","definition_ur":"\u067e\u06cc\u0634\u06c1 \u0648\u0631\u0627\u0646\u06c1 \u062a\u062d\u0631\u06cc\u0631 \u06a9\u0627 \u0627\u06cc\u06a9 \u0641\u0627\u0631\u0645\u06cc\u0679 \u062c\u0648 \u062a\u0646\u0638\u06cc\u0645 \u06a9\u06d2 \u0627\u0646\u062f\u0631 \u06cc\u0627 \u062a\u0646\u0638\u06cc\u0645\u0648\u06ba \u06a9\u06d2 \u062f\u0631\u0645\u06cc\u0627\u0646 \u062f\u0631\u062e\u0648\u0627\u0633\u062a \u062f\u06cc\u0646\u06d2\u060c \u0645\u0637\u0644\u0639 \u06a9\u0631\u0646\u06d2\u060c \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u0646\u06d2 \u06cc\u0627 \u0628\u0639\u062f \u0645\u06cc\u06ba \u0631\u0627\u0628\u0637\u06c1 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2\u060c \u062c\u0633 \u06a9\u06cc \u0648\u0627\u0636\u062d \u0633\u0627\u062e\u062a \u06c1\u0648\u062a\u06cc \u06c1\u06d2: \u0639\u0646\u0648\u0627\u0646\u060c \u0627\u0628\u062a\u062f\u0627\u0626\u06cc\u06c1\u060c \u0627\u063a\u0627\u0632\u060c \u0645\u062a\u0646\u060c \u0627\u062e\u062a\u062a\u0627\u0645 \u0627\u0648\u0631 \u062f\u0633\u062a\u062e\u0637\u06d4"},{"term":"Intercultural communication","definition_en":"The study of how people from different cultural backgrounds communicate with one another, and how cultural assumptions shape the way messages are sent, received and interpreted.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1 \u06a9\u06c1 \u0645\u062e\u062a\u0644\u0641 \u062b\u0642\u0627\u0641\u06cc \u067e\u0633 \u0645\u0646\u0638\u0631 \u06a9\u06d2 \u0644\u0648\u06af \u0627\u06cc\u06a9 \u062f\u0648\u0633\u0631\u06d2 \u06a9\u06d2 \u0633\u0627\u062a\u06be \u06a9\u06cc\u0633\u06d2 \u0631\u0627\u0628\u0637\u06c1 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u062b\u0642\u0627\u0641\u06cc \u0645\u0641\u0631\u0648\u0636\u06d2 \u067e\u06cc\u063a\u0627\u0645\u0627\u062a \u06a9\u06d2 \u0628\u06be\u06cc\u062c\u0646\u06d2\u060c \u0648\u0635\u0648\u0644 \u06a9\u0631\u0646\u06d2 \u0627\u0648\u0631 \u0627\u0646 \u06a9\u06cc \u062a\u0641\u0633\u06cc\u0631 \u06a9\u0648 \u06a9\u06cc\u0633\u06d2 \u0634\u06a9\u0644 \u062f\u06cc\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Environmental science","definition_en":"The study of the natural environment and the ways people interact with it.","definition_ur":"\u0642\u062f\u062a\u06cc \u0645\u0627\u062d\u0648\u0644 \u0627\u0648\u0631 \u0627\u0633 \u0633\u06d2 \u0627\u0646\u0633\u0627\u0646\u06cc \u062a\u0639\u0644\u0642 \u06a9\u0627 \u0645\u0637\u0627\u0644\u0639\u06c1\u06d4"},{"term":"Natural environment","definition_en":"Everything around us that is not made by people: air, water, soil, rocks, living things and the climate.","definition_ur":"\u0648\u06c1 \u0633\u0628 \u06a9\u0686\u06be \u062c\u0648 \u06c1\u0645\u0627\u0631\u06d2 \u0627\u0631\u062f \u06af\u0631\u062f \u06c1\u06d2 \u0627\u0648\u0631 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u0627 \u0628\u0646\u0627\u06cc\u0627 \u06c1\u0648\u0627 \u0646\u06c1\u06cc\u06ba: \u06c1\u0648\u0627\u060c \u067e\u0627\u0646\u06cc\u060c \u0645\u0679\u06cc\u060c \u0686\u0679\u0627\u0646\u06cc\u06ba\u060c \u062c\u0627\u0646\u062f\u0627\u0631 \u0627\u0648\u0631 \u0645\u0648\u0633\u0645\u06d4"},{"term":"Biosphere","definition_en":"The thin zone of the Earth where life exists, where the atmosphere, hydrosphere and lithosphere meet.","definition_ur":"\u0632\u0645\u06cc\u0646 \u06a9\u0627 \u0648\u06c1 \u067e\u062a\u0644\u0627 \u062d\u0635\u06c1 \u062c\u06c1\u0627\u06ba \u0632\u0646\u062f\u06af\u06cc \u067e\u0627\u0626\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2\u060c \u062c\u06c1\u0627\u06ba \u06a9\u0631\u06c1 \u06c1\u0648\u0627\u060c \u06a9\u0631\u06c1 \u0622\u0628 \u0627\u0648\u0631 \u06a9\u0631\u06c1 \u062e\u0627\u06a9 \u0622\u067e\u0633 \u0645\u06cc\u06ba \u0645\u0644\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Anthropogenic","definition_en":"Caused by people, especially of environmental change brought about by human activity.","definition_ur":"\u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u06d2 \u0633\u0628\u0628 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0627\u060c \u062e\u0627\u0635 \u0637\u0648\u0631 \u067e\u0631 \u0627\u0646\u0633\u0627\u0646\u06cc \u0633\u0631\u06af\u0631\u0645\u06cc \u0633\u06d2 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u06cc \u0645\u0627\u062d\u0648\u0644\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4"},{"term":"Ecosystem","definition_en":"A living community together with its non-living surroundings, functioning as one system.","definition_ur":"\u062c\u0627\u0646\u062f\u0627\u0631\u0648\u06ba \u06a9\u06cc \u0627\u06cc\u06a9 \u0628\u0631\u0627\u062f\u0631\u06cc \u0627\u0648\u0631 \u0627\u0646 \u06a9\u06d2 \u0628\u06d2 \u062c\u0627\u0646 \u0645\u0627\u062d\u0648\u0644\u060c \u062c\u0648 \u0627\u06cc\u06a9 \u0646\u0638\u0627\u0645 \u06a9\u06cc \u0637\u0631\u062d \u0645\u0644 \u06a9\u0631 \u06a9\u0627\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Ecosystem services","definition_en":"The benefits people receive from functioning ecosystems, such as clean water, food and protection from storms.","definition_ur":"\u06a9\u0627\u0645 \u06a9\u0631\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0645\u0627\u062d\u0648\u0644\u06cc\u0627\u062a\u06cc \u0646\u0638\u0627\u0645\u0648\u06ba \u0633\u06d2 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u0648 \u0645\u0644\u0646\u06d2 \u0648\u0627\u0644\u06d2 \u0641\u0627\u0626\u062f\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u0635\u0627\u0641 \u067e\u0627\u0646\u06cc\u060c \u062e\u0648\u0631\u0627\u06a9 \u0627\u0648\u0631 \u0637\u0648\u0641\u0627\u0646\u0648\u06ba \u0633\u06d2 \u062d\u0641\u0627\u0638\u062a\u06d4"},{"term":"Natural resources","definition_en":"Anything from the environment that people use to meet their needs, such as water, soil, minerals and forests.","definition_ur":"\u0645\u0627\u062d\u0648\u0644 \u0633\u06d2 \u0645\u0644\u0646\u06d2 \u0648\u0627\u0644\u06cc \u0648\u06c1 \u06c1\u0631 \u0686\u06cc\u0632 \u062c\u0648 \u0627\u0646\u0633\u0627\u0646 \u0627\u067e\u0646\u06cc \u0636\u0631\u0648\u0631\u06cc\u0627\u062a \u067e\u0648\u0631\u06cc \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u062c\u06cc\u0633\u06d2 \u067e\u0627\u0646\u06cc\u060c \u0645\u0679\u06cc\u060c \u0645\u0639\u062f\u0646\u06cc\u0627\u062a \u0627\u0648\u0631 \u062c\u0646\u06af\u0644\u0627\u062a\u06d4"},{"term":"Renewable resources","definition_en":"Resources that renew themselves on a human timescale if they are not overused.","definition_ur":"\u0648\u06c1 \u0648\u0633\u0627\u0626\u0644 \u062c\u0648 \u0645\u0646\u0627\u0633\u0628 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0645\u06cc\u06ba \u0627\u0646\u0633\u0627\u0646\u06cc \u062f\u0648\u0631 \u0645\u06cc\u06ba \u062f\u0648\u0628\u0627\u0631\u06c1 \u067e\u06cc\u062f\u0627 \u06c1\u0648 \u062c\u0627\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Non-renewable resources","definition_en":"Resources that exist as fixed stocks and cannot be rebuilt on a human timescale.","definition_ur":"\u0648\u06c1 \u0648\u0633\u0627\u0626\u0644 \u062c\u0648 \u0645\u0642\u0631\u0631\u06c1 \u0645\u0642\u062f\u0627\u0631 \u0645\u06cc\u06ba \u0645\u0648\u062c\u0648\u062f \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u0627\u0646\u0633\u0627\u0646\u06cc \u062f\u0648\u0631 \u0645\u06cc\u06ba \u062f\u0648\u0628\u0627\u0631\u06c1 \u0646\u06c1\u06cc\u06ba \u0628\u0646 \u0633\u06a9\u062a\u06d2\u06d4"},{"term":"Sustainability","definition_en":"The test of whether an action can continue, as it is, without exhausting what it depends on.","definition_ur":"\u0627\u0633 \u0628\u0627\u062a \u06a9\u0627 \u0627\u0645\u062a\u062d\u0627\u0646 \u06a9\u06c1 \u06a9\u0648\u0626\u06cc \u0639\u0645\u0644 \u0627\u0633\u06cc \u0637\u0631\u062d \u062c\u0627\u0631\u06cc \u0631\u06c1 \u0633\u06a9\u062a\u0627 \u06c1\u06d2 \u06cc\u0627 \u0646\u06c1\u06cc\u06ba\u060c \u0628\u063a\u06cc\u0631 \u0627\u0633 \u0686\u06cc\u0632 \u06a9\u0648 \u062e\u062a\u0645 \u06a9\u06cc\u06d2 \u062c\u0633 \u067e\u0631 \u0648\u06c1 \u0645\u0646\u062d\u0635\u0631 \u06c1\u06d2\u06d4"},{"term":"Water security","definition_en":"Reliable access to water of acceptable quality and quantity for health and livelihoods.","definition_ur":"\u0635\u062d\u062a \u0627\u0648\u0631 \u0631\u0648\u0632\u06af\u0627\u0631 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0642\u0627\u0628\u0644\u0650 \u0642\u0628\u0648\u0644 \u0645\u0639\u06cc\u0627\u0631 \u0627\u0648\u0631 \u0645\u0642\u062f\u0627\u0631 \u06a9\u06d2 \u067e\u0627\u0646\u06cc \u062a\u06a9 \u0642\u0627\u0628\u0644\u0650 \u0628\u06be\u0631\u0648\u0633\u06c1 \u0631\u0633\u0627\u0626\u06cc\u06d4"},{"term":"Water scarcity","definition_en":"A situation where per-person water availability falls below the level a population needs, usually measured per year.","definition_ur":"\u0648\u06c1 \u0635\u0648\u0631\u062a\u062d\u0627\u0644 \u062c\u06c1\u0627\u06ba \u0641\u06cc \u0641\u0631\u062f \u067e\u0627\u0646\u06cc \u06a9\u06cc \u062f\u0633\u062a\u06cc\u0627\u0628\u06cc \u0622\u0628\u0627\u062f\u06cc \u06a9\u06cc \u0636\u0631\u0648\u0631\u062a \u0633\u06d2 \u06a9\u0645 \u06c1\u0648 \u062c\u0627\u0626\u06d2\u060c \u0639\u0645\u0648\u0645\u0627\u064b \u0633\u0627\u0644\u0627\u0646\u06c1 \u0645\u0627\u067e\u06cc \u062c\u0627\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Water pollution","definition_en":"The addition of substances or heat to water at a level that harms its use by people or by living things.","definition_ur":"\u067e\u0627\u0646\u06cc \u0645\u06cc\u06ba \u0627\u06cc\u0633\u06d2 \u0645\u0627\u062f\u0648\u06ba \u06cc\u0627 \u062d\u0631\u0627\u0631\u062a \u06a9\u0627 \u0627\u0636\u0627\u0641\u06c1 \u062c\u0648 \u0627\u0633 \u06a9\u06d2 \u0627\u0646\u0633\u0627\u0646\u06cc \u06cc\u0627 \u062d\u06cc\u0627\u062a\u06cc \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Pathogen","definition_en":"An organism, such as a bacterium or virus, that causes disease.","definition_ur":"\u06a9\u0648\u0626\u06cc \u062c\u0627\u0646\u062f\u0627\u0631\u060c \u062c\u06cc\u0633\u06d2 \u0628\u06cc\u06a9\u0679\u06cc\u0631\u06cc\u0627 \u06cc\u0627 \u0648\u0627\u0626\u0631\u0633\u060c \u062c\u0648 \u0628\u06cc\u0645\u0627\u0631\u06cc \u067e\u06cc\u062f\u0627 \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Eutrophication","definition_en":"The over-fertilisation of a water body by nutrients, causing an algal bloom followed by a collapse in oxygen.","definition_ur":"\u063a\u0630\u0627\u0626\u06cc \u0645\u0627\u062f\u0648\u06ba \u0633\u06d2 \u06a9\u0633\u06cc \u0622\u0628\u06cc \u062c\u0633\u0645 \u06a9\u06cc \u0632\u06cc\u0627\u062f\u06c1 \u06a9\u06be\u0627\u062f \u067e\u0691\u0646\u0627\u060c \u062c\u0633 \u0633\u06d2 \u0627\u0644\u06af\u06cc \u067e\u06be\u06cc\u0644\u062a\u06cc \u06c1\u06d2 \u0627\u0648\u0631 \u067e\u06be\u0631 \u0622\u06a9\u0633\u06cc\u062c\u0646 \u0634\u062f\u06cc\u062f \u06a9\u0645 \u06c1\u0648 \u062c\u0627\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Effluent","definition_en":"The liquid waste a facility or household discharges.","definition_ur":"\u06a9\u0633\u06cc \u0627\u062f\u0627\u0631\u06d2 \u06cc\u0627 \u06af\u06be\u0631 \u0633\u06d2 \u062e\u0627\u0631\u062c \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0645\u0627\u0626\u0639 \u0641\u0636\u0644\u06c1\u06d4"},{"term":"Municipal solid waste","definition_en":"The everyday waste of households, shops, schools and offices.","definition_ur":"\u06af\u06be\u0631\u0648\u06ba\u060c \u062f\u06a9\u0627\u0646\u0648\u06ba\u060c \u0627\u0633\u06a9\u0648\u0644\u0648\u06ba \u0627\u0648\u0631 \u062f\u0641\u062a\u0631\u0648\u06ba \u06a9\u0627 \u0631\u0648\u0632\u0645\u0631\u06c1 \u06a9\u0627 \u06a9\u0686\u0631\u0627\u06d4"},{"term":"Waste hierarchy","definition_en":"The ordering of waste options from best to worst: reduce, reuse, recycle, recover, dispose.","definition_ur":"\u06a9\u0686\u0631\u06d2 \u06a9\u06d2 \u0627\u0646\u062a\u0638\u0627\u0645 \u06a9\u06d2 \u0637\u0631\u06cc\u0642\u0648\u06ba \u06a9\u06cc \u0628\u06c1\u062a\u0631\u06cc\u0646 \u0633\u06d2 \u0628\u062f\u062a\u0631\u06cc\u0646 \u062a\u0631\u062a\u06cc\u0628: \u06a9\u0645 \u06a9\u0631\u06cc\u06ba\u060c \u062f\u0648\u0628\u0627\u0631\u06c1 \u0627\u0633\u062a\u0639\u0645\u0627\u0644\u060c \u0631\u06cc \u0633\u0627\u0626\u06cc\u06a9\u0644\u060c \u0628\u062d\u0627\u0644\u06cc\u060c \u0627\u062e\u0631\u0627\u062c\u06d4"},{"term":"Recycling","definition_en":"Turning used material into new material, which depends on clean, separated collection.","definition_ur":"\u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u0634\u062f\u06c1 \u0645\u0627\u062f\u06d2 \u06a9\u0648 \u0646\u06cc\u0627 \u0645\u0648\u0627\u062f \u0628\u0646\u0627\u0646\u0627\u060c \u062c\u0648 \u0635\u0627\u0641 \u0627\u0648\u0631 \u0627\u0644\u06af \u06a9\u06cc\u06d2 \u06af\u0626\u06d2 \u06a9\u0686\u0631\u06d2 \u067e\u0631 \u0645\u0646\u062d\u0635\u0631 \u06c1\u06d2\u06d4"},{"term":"Hazardous waste","definition_en":"Waste whose properties, infectious, toxic, flammable or corrosive, make it dangerous to people or the environment.","definition_ur":"\u0648\u06c1 \u06a9\u0686\u0631\u0627 \u062c\u0633 \u06a9\u06cc \u062e\u0635\u0648\u0635\u06cc\u0627\u062a\u060c \u0639\u062f\u0648\u06cc\u060c \u0632\u06c1\u0631\u06cc\u0644\u06cc\u060c \u0622\u062a\u0634 \u06af\u06cc\u0631 \u06cc\u0627 \u06a9\u0627\u0631\u0622\u0645\u062f\u060c \u0627\u0633\u06d2 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06cc\u0627 \u0645\u0627\u062d\u0648\u0644 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062e\u0637\u0631\u0646\u0627\u06a9 \u0628\u0646\u0627\u062a\u06cc \u06c1\u06cc\u06ba\u06d4"},{"term":"Sanitation","definition_en":"The provision of facilities and services for the safe disposal of human waste, including latrines, sewerage and treatment.","definition_ur":"\u0627\u0646\u0633\u0627\u0646\u06cc \u0641\u0636\u0644\u06d2 \u06a9\u06d2 \u0645\u062d\u0641\u0648\u0638 \u0627\u062e\u0631\u0627\u062c \u06a9\u06cc \u0633\u06c1\u0648\u0644\u06cc\u0627\u062a \u0627\u0648\u0631 \u062e\u062f\u0645\u0627\u062a\u060c \u0628\u0634\u0645\u0648\u0644 \u0628\u06cc\u062a \u0627\u0644\u062e\u0644\u0627\u060c \u06af\u0646\u062f\u06d2 \u067e\u0627\u0646\u06cc \u06a9\u0627 \u0646\u0638\u0627\u0645 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u0627 \u0639\u0644\u0627\u062c\u06d4"},{"term":"Air pollution","definition_en":"The presence of substances in the air at levels that harm people, other living things or materials.","definition_ur":"\u06c1\u0648\u0627 \u0645\u06cc\u06ba \u0627\u06cc\u0633\u06d2 \u0645\u0627\u062f\u0648\u06ba \u06a9\u06cc \u0645\u0648\u062c\u0648\u062f\u06af\u06cc \u062c\u0648 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba\u060c \u062f\u0648\u0633\u0631\u06d2 \u062c\u0627\u0646\u062f\u0627\u0631\u0648\u06ba \u06cc\u0627 \u0686\u06cc\u0632\u0648\u06ba \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Noise pollution","definition_en":"Sound loud or persistent enough to harm health or wellbeing.","definition_ur":"\u0627\u06cc\u0633\u06cc \u0622\u0648\u0627\u0632 \u062c\u0648 \u0627\u062a\u0646\u06cc \u0628\u0644\u0646\u062f \u06cc\u0627 \u0645\u0633\u0644\u0633\u0644 \u06c1\u0648 \u06a9\u06c1 \u0635\u062d\u062a \u06cc\u0627 \u0633\u06a9\u0648\u0646 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Hazard","definition_en":"Anything with the potential to cause harm; the condition itself, not the event.","definition_ur":"\u0648\u06c1 \u06c1\u0631 \u0686\u06cc\u0632 \u062c\u0633 \u0645\u06cc\u06ba \u0646\u0642\u0635\u0627\u0646 \u06a9\u06cc \u0635\u0644\u0627\u062d\u06cc\u062a \u06c1\u0648\u061b \u062d\u0627\u0644\u062a \u062e\u0648\u062f\u060c \u0648\u0627\u0642\u0639\u06c1 \u0646\u06c1\u06cc\u06ba\u06d4"},{"term":"Health, safety and environment","definition_en":"The field that studies hazards to people and the environment together, often abbreviated HSE.","definition_ur":"\u0648\u06c1 \u0639\u0644\u0645 \u062c\u0648 \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u0627\u0648\u0631 \u0645\u0627\u062d\u0648\u0644 \u06a9\u06d2 \u062e\u0637\u0631\u0627\u062a \u06a9\u0648 \u0627\u06cc\u06a9 \u0633\u0627\u062a\u06be \u067e\u0691\u06be\u062a\u0627 \u06c1\u06d2\u060c \u0639\u0627\u0645 \u0637\u0648\u0631 \u067e\u0631 \u0627\u06cc\u0686 \u0627\u06cc\u0633 \u0627\u06cc\u06d4"},{"term":"Environmental safety","definition_en":"Managing the surroundings, a school, worksite, water or air, so that they do not injure the people inside them.","definition_ur":"\u0645\u0627\u062d\u0648\u0644 \u06a9\u0648 \u0627\u06cc\u0633\u06cc \u062d\u0627\u0644\u062a \u0645\u06cc\u06ba \u0631\u06a9\u06be\u0646\u0627\u060c \u0627\u0633\u06a9\u0648\u0644\u060c \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1\u060c \u067e\u0627\u0646\u06cc \u06cc\u0627 \u06c1\u0648\u0627\u060c \u06a9\u06c1 \u0648\u06c1 \u0627\u0646\u062f\u0631 \u0645\u0648\u062c\u0648\u062f \u0627\u0646\u0633\u0627\u0646\u0648\u06ba \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u0646\u06c1 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Risk","definition_en":"The chance and the seriousness of harm actually occurring, in real conditions.","definition_ur":"\u062d\u0642\u06cc\u0642\u06cc \u062d\u0627\u0644\u0627\u062a \u0645\u06cc\u06ba \u0646\u0642\u0635\u0627\u0646 \u06a9\u06d2 \u0648\u0627\u0642\u0639 \u06c1\u0648\u0646\u06d2 \u06a9\u0627 \u0627\u0645\u06a9\u0627\u0646 \u0627\u0648\u0631 \u0627\u0633 \u06a9\u06cc \u0634\u062f\u062a\u06d4"},{"term":"OSH management system","definition_en":"The organised set of elements, policy, organisation, planning, procedures, checking and review, through which a workplace manages its hazards continuously.","definition_ur":"\u0627\u062f\u0627\u0631\u06d2 \u06a9\u06d2 \u0648\u06c1 \u0645\u0646\u0638\u0645 \u0639\u0646\u0627\u0635\u0631\u060c \u067e\u0627\u0644\u06cc\u0633\u06cc\u060c \u062a\u0646\u0638\u06cc\u0645\u060c \u0645\u0646\u0635\u0648\u0628\u06c1 \u0628\u0646\u062f\u06cc\u060c \u0637\u0631\u06cc\u0642\u06c1 \u06a9\u0627\u0631\u060c \u062c\u0627\u0646\u0686 \u0627\u0648\u0631 \u062c\u0627\u0626\u0632\u06c1\u060c \u062c\u0646 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u062e\u0637\u0631\u0627\u062a \u06a9\u0648 \u0645\u0633\u0644\u0633\u0644 \u0633\u0646\u0628\u06be\u0627\u0644\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Incident","definition_en":"Any unplanned event that did or could have caused harm; the injury, the fatality and the near-miss are its grades.","definition_ur":"\u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u063a\u06cc\u0631 \u0645\u0646\u0635\u0648\u0628\u06c1 \u0628\u0646\u062f \u0648\u0627\u0642\u0639\u06c1 \u062c\u0633 \u0646\u06d2 \u0646\u0642\u0635\u0627\u0646 \u06a9\u06cc\u0627 \u06c1\u0648 \u06cc\u0627 \u06a9\u0631 \u0633\u06a9\u062a\u0627 \u062a\u06be\u0627\u061b \u0632\u062e\u0645\u060c \u0645\u0648\u062a \u0627\u0648\u0631 \u0628\u0686\u0627 \u0648\u0627\u0642\u0639\u06c1 \u0627\u0633 \u06a9\u06d2 \u062f\u0631\u062c\u06d2 \u06c1\u06cc\u06ba\u06d4"},{"term":"Internal control","definition_en":"The measures an organisation uses to make sure its own rules are actually followed: authorisation, records, supervision and review.","definition_ur":"\u0648\u06c1 \u0627\u0642\u062f\u0627\u0645\u0627\u062a \u062c\u0648 \u06a9\u0648\u0626\u06cc \u0627\u062f\u0627\u0631\u06c1 \u0627\u067e\u0646\u06d2 \u0642\u0648\u0627\u0639\u062f \u06a9\u06d2 \u0627\u0635\u0644 \u0645\u06cc\u06ba \u0645\u0627\u0646\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06a9\u0631\u062a\u0627 \u06c1\u06d2: \u0627\u062c\u0627\u0632\u062a\u060c \u0631\u06cc\u06a9\u0627\u0631\u0688\u060c \u0646\u06af\u0631\u0627\u0646\u06cc \u0627\u0648\u0631 \u062c\u0627\u0626\u0632\u06c1\u06d4"},{"term":"OHS professional","definition_en":"The person a workplace employs to make its safety work: adviser, trainer, inspector, investigator, record keeper and communicator.","definition_ur":"\u0648\u06c1 \u0634\u062e\u0635 \u062c\u0633\u06d2 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u062d\u0641\u0627\u0638\u062a \u06a9\u0627 \u06a9\u0627\u0645 \u0633\u0648\u0646\u067e\u062a\u06cc \u06c1\u06d2: \u0645\u0634\u06cc\u0631\u060c \u062a\u0631\u0628\u06cc\u062a \u06a9\u0627\u0631\u060c \u0645\u0639\u0627\u0626\u0646\u06c1 \u06a9\u0627\u0631\u060c \u062a\u0641\u062a\u06cc\u0634 \u06a9\u0627\u0631\u060c \u0631\u06cc\u06a9\u0627\u0631\u0688 \u0631\u06a9\u06be\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u0648\u0631 \u0631\u0627\u0628\u0637\u06c1 \u06a9\u0627\u0631\u06d4"},{"term":"Incident pyramid","definition_en":"The model in which every serious injury sits on a much wider base of minor injuries, near-misses and unsafe acts sharing the same causes.","definition_ur":"\u0648\u06c1 \u0645\u0627\u0688\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u06c1\u0631 \u0633\u0646\u06af\u06cc\u0646 \u0632\u062e\u0645 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u0686\u06be\u0648\u0679\u06d2 \u0632\u062e\u0645\u0648\u06ba\u060c \u0628\u0686\u06d2 \u0648\u0627\u0642\u0639\u0627\u062a \u0627\u0648\u0631 \u063a\u06cc\u0631 \u0645\u062d\u0641\u0648\u0638 \u0639\u0645\u0644 \u06a9\u06cc \u0648\u0633\u06cc\u0639 \u0628\u0646\u06cc\u0627\u062f \u06c1\u0648\u062a\u06cc \u06c1\u06d2\u060c \u0633\u0628 \u0627\u06cc\u06a9 \u06c1\u06cc \u0627\u0633\u0628\u0627\u0628 \u0633\u06d2\u06d4"},{"term":"Swiss cheese model","definition_en":"The model of accident causation in which defences are slices with holes, and harm passes through when the holes line up.","definition_ur":"\u062d\u0627\u062f\u062b\u06d2 \u06a9\u06d2 \u0633\u0628\u0628 \u06a9\u0627 \u0648\u06c1 \u0645\u0627\u0688\u0644 \u062c\u0633 \u0645\u06cc\u06ba \u062f\u0641\u0627\u0639 \u0633\u0648\u0631\u0627\u062e \u0648\u0627\u0644\u06cc \u067e\u0646\u06cc\u0631 \u06a9\u06cc \u0633\u0644\u0627\u0626\u06cc\u06ba \u06c1\u06cc\u06ba\u060c \u0627\u0648\u0631 \u0646\u0642\u0635\u0627\u0646 \u062a\u0628 \u06af\u0632\u0631\u062a\u0627 \u06c1\u06d2 \u062c\u0628 \u0633\u0648\u0631\u0627\u062e \u0627\u06cc\u06a9 \u0644\u0627\u0626\u0646 \u0645\u06cc\u06ba \u0622 \u062c\u0627\u0626\u06cc\u06ba\u06d4"},{"term":"Organizational environment","definition_en":"The workplace\'s own climate: how work is divided, how pressure is applied, and how bad news travels.","definition_ur":"\u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u06a9\u0627 \u0627\u067e\u0646\u0627 \u0645\u0627\u062d\u0648\u0644: \u06a9\u0627\u0645 \u06a9\u06cc \u062a\u0642\u0633\u06cc\u0645\u060c \u062f\u0628\u0627\u0624 \u06a9\u0627 \u0627\u0646\u062f\u0627\u0632\u060c \u0627\u0648\u0631 \u0628\u0631\u06cc \u062e\u0628\u0631 \u06a9\u0627 \u0633\u0641\u0631\u06d4"},{"term":"HSE plan","definition_en":"The document that turns statutes and the PDCA cycle into a named, dated commitment for one workplace.","definition_ur":"\u0648\u06c1 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u062c\u0648 \u0642\u0648\u0627\u0646\u06cc\u0646 \u0627\u0648\u0631 \u067e\u06cc \u0688\u06cc \u0633\u06cc \u0627\u06d2 \u0686\u06a9\u0631 \u06a9\u0648 \u06a9\u0633\u06cc \u0627\u06cc\u06a9 \u06a9\u0627\u0645 \u06a9\u06cc \u062c\u06af\u06c1 \u06a9\u06d2 \u0646\u0627\u0645\u0632\u062f\u060c \u062a\u0627\u0631\u06cc\u062e \u0648\u0627\u0644\u06d2 \u0648\u0639\u062f\u06d2 \u0645\u06cc\u06ba \u0628\u062f\u0644\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Toxic agent","definition_en":"A substance that harms a living organism when it reaches a sensitive site in enough amount.","definition_ur":"\u0648\u06c1 \u0645\u0627\u062f\u06c1 \u062c\u0648 \u06a9\u0627\u0641\u06cc \u0645\u0642\u062f\u0627\u0631 \u0645\u06cc\u06ba \u06a9\u0633\u06cc \u062d\u0633\u0627\u0633 \u062c\u06af\u06c1 \u067e\u0631 \u067e\u06c1\u0646\u0686 \u06a9\u0631 \u062c\u0627\u0646\u062f\u0627\u0631 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u062f\u06cc\u062a\u0627 \u06c1\u06d2\u06d4"},{"term":"Xenobiotic","definition_en":"Any chemical foreign to the body: pesticides, drugs, industrial solvents, pollutants.","definition_ur":"\u062c\u0633\u0645 \u06a9\u06d2 \u0644\u06cc\u06d2 \u063a\u06cc\u0631 \u0645\u0644\u06a9\u06cc \u06a9\u0648\u0626\u06cc \u0628\u06be\u06cc \u06a9\u06cc\u0645\u06cc\u06a9\u0644: \u06a9\u06cc\u0691\u06d2 \u0645\u0627\u0631 \u0627\u062f\u0648\u06cc\u0627\u062a\u060c \u062f\u0648\u0627\u0626\u06cc\u06ba\u060c \u0635\u0646\u0639\u062a\u06cc \u0633\u0627\u0644\u0648\u06cc\u0646\u0679\u060c \u0622\u0644\u0648\u062f\u06af\u06cc\u0627\u06ba\u06d4"},{"term":"Biotransformation","definition_en":"The liver chemical reworking of a xenobiotic that prepares it for export.","definition_ur":"\u062c\u06af\u0631 \u06a9\u06cc \u0648\u06c1 \u06a9\u06cc\u0645\u06cc\u0627\u0626\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u062c\u0648 \u0632\u06cc\u0646\u0648 \u0628\u0627\u0626\u06cc\u0648\u0679\u06a9 \u06a9\u0648 \u0627\u062e\u0631\u0627\u062c \u06a9\u06d2 \u0644\u06cc\u06d2 \u062a\u06cc\u0627\u0631 \u06a9\u0631\u062a\u06cc \u06c1\u06d2\u06d4"},{"term":"Detoxification","definition_en":"A biotransformation outcome in which the product is less harmful and exportable.","definition_ur":"\u062d\u06cc\u0627\u062a\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u0648\u06c1 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0645\u0635\u0646\u0648\u0639 \u06a9\u0645 \u0646\u0642\u0635\u0627\u0646 \u062f\u06c1 \u0627\u0648\u0631 \u0646\u06a9\u0644\u0646\u06d2 \u06a9\u06d2 \u0642\u0627\u0628\u0644 \u06c1\u0648\u06d4"},{"term":"Bioactivation","definition_en":"A biotransformation outcome in which the product is more poisonous than the original.","definition_ur":"\u062d\u06cc\u0627\u062a\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u0627 \u0648\u06c1 \u0646\u062a\u06cc\u062c\u06c1 \u062c\u0633 \u0645\u06cc\u06ba \u0645\u0635\u0646\u0648\u0639 \u0627\u0635\u0644 \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0632\u06c1\u0631\u06cc\u0644\u0627 \u06c1\u0648\u06d4"},{"term":"Multilateral environmental agreement","definition_en":"A treaty among many states that commits them to manage a shared environmental problem, through ratification and reporting cycles.","definition_ur":"\u06a9\u0626\u06cc \u0631\u06cc\u0627\u0633\u062a\u0648\u06ba \u06a9\u0627 \u0648\u06c1 \u0645\u0639\u0627\u06c1\u062f\u06c1 \u062c\u0648 \u0627\u0646\u06c1\u06cc\u06ba \u0645\u0634\u062a\u0631\u06a9\u06c1 \u0645\u0627\u062d\u0648\u0644\u06cc\u0627\u062a\u06cc \u0645\u0633\u0626\u0644\u06d2 \u0633\u0646\u0628\u06be\u0627\u0644\u0646\u06d2 \u06a9\u0627 \u067e\u0627\u0628\u0646\u062f \u06a9\u0631\u062a\u0627 \u06c1\u06d2\u060c \u062a\u0648\u062b\u06cc\u0642 \u0627\u0648\u0631 \u0631\u067e\u0648\u0631\u0679\u0646\u06af \u06a9\u06d2 \u0686\u06a9\u0631 \u06a9\u06d2 \u0630\u0631\u06cc\u0639\u06d2\u06d4"},{"term":"Sustainable Development Goals","definition_en":"Seventeen goals for 2030 adopted by all United Nations member states in 2015, each with targets and indicators.","definition_ur":"\u0633\u062a\u0631\u06c1 \u0627\u06c1\u062f\u0627\u0641 \u0628\u0631\u0627\u0626\u06d2 2030\u060c \u062a\u0645\u0627\u0645 \u0627\u0642\u0648\u0627\u0645 \u0645\u062a\u062d\u062f\u06c1 \u0631\u06a9\u0646 \u0631\u06cc\u0627\u0633\u062a\u0648\u06ba \u0646\u06d2 2015 \u0645\u06cc\u06ba \u0627\u067e\u0646\u0627\u0626\u06d2\u060c \u06c1\u0631 \u0627\u06cc\u06a9 \u0645\u06cc\u06ba \u0646\u0634\u0627\u0646 \u0627\u0648\u0631 \u067e\u06cc\u0645\u0627\u0646\u06d2\u06d4"},{"term":"Toxicology","definition_en":"The study of the adverse effects of chemicals on living organisms.","definition_ur":"\u06a9\u06cc\u0645\u06cc\u06a9\u0644\u0632 \u06a9\u06d2 \u062c\u0627\u0646\u062f\u0627\u0631\u0648\u06ba \u067e\u0631 \u0646\u0642\u0635\u0627\u0646 \u062f\u06c1 \u0627\u062b\u0631\u0627\u062a \u06a9\u0627 \u0639\u0644\u0645\u06d4"},{"term":"Dose","definition_en":"The amount of a substance that reaches a sensitive site; the founding question of toxicology.","definition_ur":"\u06a9\u0633\u06cc \u0645\u0627\u062f\u06d2 \u06a9\u06cc \u0648\u06c1 \u0645\u0642\u062f\u0627\u0631 \u062c\u0648 \u062d\u0633\u0627\u0633 \u062c\u06af\u06c1 \u062a\u06a9 \u067e\u06c1\u0646\u0686\u06d2\u061b \u0632\u06c1\u0631\u06cc\u0644\u06cc \u0645\u0627\u062f\u0648\u06ba \u06a9\u06d2 \u0639\u0644\u0645 \u06a9\u0627 \u0628\u0646\u06cc\u0627\u062f\u06cc \u0633\u0648\u0627\u0644\u06d4"},{"term":"Acute effect","definition_en":"An effect appearing quickly after a single or short exposure.","definition_ur":"\u0627\u06cc\u06a9 \u06cc\u0627 \u0645\u062e\u062a\u0635\u0631 \u0631\u0627\u0628\u0637\u06d2 \u06a9\u06d2 \u0628\u0639\u062f \u062c\u0644\u062f \u0638\u0627\u06c1\u0631 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u062b\u0631\u06d4"},{"term":"Chronic effect","definition_en":"An effect developing slowly over long, often low-level exposure.","definition_ur":"\u0637\u0648\u06cc\u0644\u060c \u0627\u06a9\u062b\u0631 \u06a9\u0645 \u0633\u0637\u062d \u0631\u0627\u0628\u0637\u06d2 \u067e\u0631 \u0622\u06c1\u0633\u062a\u06c1 \u0622\u06c1\u0633\u062a\u06c1 \u067e\u06cc\u062f\u0627 \u06c1\u0648\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0627\u062b\u0631\u06d4"},{"term":"Genotoxic agent","definition_en":"An agent that damages DNA, the cell instruction manual.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0688\u06cc \u0627\u06cc\u0646 \u0627\u06d2\u060c \u062e\u0644\u06cc\u06d2 \u06a9\u06cc \u06c1\u062f\u0627\u06cc\u062a \u0646\u0627\u0645\u06c1\u060c \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u067e\u06c1\u0646\u0686\u0627\u0626\u06d2\u06d4"},{"term":"Mutagen","definition_en":"An agent that causes changes in the DNA sequence.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0688\u06cc \u0627\u06cc\u0646 \u0627\u06d2 \u06a9\u06cc \u062a\u0631\u062a\u06cc\u0628 \u0645\u06cc\u06ba \u062a\u0628\u062f\u06cc\u0644\u06cc \u067e\u06cc\u062f\u0627 \u06a9\u0631\u06d2\u06d4"},{"term":"Teratogen","definition_en":"An agent that harms the developing unborn child, with timing as decisive as dose.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0628\u0691\u06be\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u0646\u0627\u062c\u0627\u0626\u0632 \u0628\u0686\u06d2 \u06a9\u0648 \u0646\u0642\u0635\u0627\u0646 \u062f\u06d2\u061b \u0648\u0642\u062a \u062e\u0648\u0631\u0627\u06a9 \u062c\u06cc\u0633\u0627 \u06c1\u06cc \u0641\u06cc\u0635\u0644\u06c1 \u06a9\u0646\u06d4"},{"term":"Carcinogen","definition_en":"An agent that causes cancer.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0633\u0631\u0637\u0627\u0646 \u067e\u06cc\u062f\u0627 \u06a9\u0631\u06d2\u06d4"},{"term":"Sensitizer","definition_en":"An agent that trains the immune system to overreact to later exposures.","definition_ur":"\u0648\u06c1 \u0639\u0646\u0635\u0631 \u062c\u0648 \u0645\u062f\u0627\u0641\u0639\u062a \u06a9\u0648 \u0628\u0639\u062f \u06a9\u06d2 \u0631\u0627\u0628\u0637\u0648\u06ba \u067e\u0631 \u062d\u062f \u0633\u06d2 \u0632\u06cc\u0627\u062f\u06c1 \u0631\u062f\u0639\u0645\u0644 \u0633\u06a9\u06be\u0627 \u062f\u06d2\u06d4"},{"term":"Essentiality","definition_en":"The property of being required for life, with toxicity waiting higher up the same ladder.","definition_ur":"\u0632\u0646\u062f\u06af\u06cc \u06a9\u06d2 \u0644\u06cc\u06d2 \u0636\u0631\u0648\u0631\u06cc \u06c1\u0648\u0646\u06d2 \u06a9\u06cc \u0635\u0641\u062a\u061b \u0627\u0633\u06cc \u0632\u06cc\u0646\u06d2 \u067e\u0631 \u0627\u0648\u067e\u0631 \u0632\u06c1\u0631\u06cc\u0644\u06cc \u06c1\u0648\u0646\u0627 \u0631\u06a9\u06be\u0627 \u06c1\u06d2\u06d4"},{"term":"Bioaccumulation","definition_en":"The build-up of a substance within one organism when entry outpaces exit.","definition_ur":"\u062c\u0628 \u06a9\u0648\u0626\u06cc \u0645\u0627\u062f\u06c1 \u0627\u0646\u062f\u0631 \u0622\u0646\u0627 \u0628\u0627\u06c1\u0631 \u062c\u0627\u0646\u06d2 \u0633\u06d2 \u062a\u06cc\u0632 \u06c1\u0648 \u062a\u0648 \u0627\u06cc\u06a9 \u062c\u0627\u0646\u062f\u0627\u0631 \u0645\u06cc\u06ba \u062c\u0645\u0639 \u06c1\u0648\u0646\u0627\u06d4"},{"term":"Smog","definition_en":"A visible mixture of pollutants held near the ground: sulfurous in winter, photochemical in summer.","definition_ur":"\u0632\u0645\u06cc\u0646 \u06a9\u06d2 \u0642\u0631\u06cc\u0628 \u0642\u06cc\u062f \u0622\u0644\u0648\u062f\u06af\u06cc\u0648\u06ba \u06a9\u0627 \u062f\u06a9\u06be\u0627\u0626\u06cc \u062f\u06cc\u0646\u06d2 \u0648\u0627\u0644\u0627 \u0645\u0631\u06a9\u0628: \u0633\u0631\u062f\u06cc\u0648\u06ba \u0645\u06cc\u06ba \u0633\u0644\u0641\u0631\u06cc\u060c \u06af\u0631\u0645\u06cc\u0648\u06ba \u0645\u06cc\u06ba \u0641\u0648\u0679\u0648 \u06a9\u06cc\u0645\u06cc\u06a9\u0644\u06d4"},{"term":"Mitigation","definition_en":"Reducing the causes of climate change, emissions and deforestation, for the shared future.","definition_ur":"\u0645\u0648\u0633\u0645\u06cc\u0627\u062a\u06cc \u062a\u0628\u062f\u06cc\u0644\u06cc \u06a9\u06d2 \u0627\u0633\u0628\u0627\u0628 \u06af\u06be\u0679\u0627\u0646\u0627\u060c \u0627\u062e\u0631\u0627\u062c \u0627\u0648\u0631 \u062c\u0646\u06af\u0644\u0627\u062a \u06a9\u0679\u0627\u0626\u06cc\u060c \u0645\u0634\u062a\u0631\u06a9\u06c1 \u0645\u0633\u062a\u0642\u0628\u0644 \u06a9\u06d2 \u0644\u06cc\u06d2\u06d4"},{"term":"Adaptation","definition_en":"Softening the harms of the climate impacts already arriving: heat plans, flood-proofing, early warning.","definition_ur":"\u067e\u06c1\u0646\u0686 \u0686\u0644\u06d2 \u0645\u0648\u0633\u0645\u06cc \u0627\u062b\u0631\u0627\u062a \u06a9\u06d2 \u0646\u0642\u0635\u0627\u0646 \u06a9\u0648 \u0646\u0631\u0645 \u06a9\u0631\u0646\u0627: \u06af\u0631\u0645\u06cc \u0645\u0646\u0635\u0648\u0628\u06d2\u060c \u0633\u06cc\u0644 \u0633\u06d2 \u0628\u0686\u0627\u0624\u060c \u0627\u0628\u062a\u062f\u0627\u0626\u06cc \u0627\u0637\u0644\u0627\u0639\u06d4"},{"term":"Bio-magnification","definition_en":"The rise in concentration of a substance up the food chain as each predator eats many prey.","definition_ur":"\u063a\u0630\u0627\u0626\u06cc \u0632\u0646\u062c\u06cc\u0631 \u067e\u0631 \u0686\u0691\u06be\u062a\u06d2 \u06c1\u0648\u0626\u06d2 \u06a9\u0633\u06cc \u0645\u0627\u062f\u06d2 \u06a9\u06cc \u062d\u0631\u0627\u0633\u062a\u06cc \u0628\u0691\u06be\u0646\u0627\u060c \u062c\u0628 \u06c1\u0631 \u0634\u06a9\u0627\u0631\u06cc \u0628\u06c1\u062a \u0634\u06a9\u0627\u0631 \u06a9\u06be\u0627\u062a\u0627 \u06c1\u06d2\u06d4"}]');var o=i(4848);function a(e){var n=e.term,i=e.children,a=t.find(function(e){return e.term===n}),r=a?"EN: "+a.definition_en+"\nUR: "+a.definition_ur:n;return(0,o.jsx)("abbr",{className:"glossary-term",title:r,"aria-label":r,tabIndex:0,children:null!=i?i:n})}},6606(e,n,i){i.d(n,{A:()=>o});i(6540);var t=i(4848);function o(e){var n=e.label,i=void 0===n?"Print / Save as PDF":n;return(0,t.jsxs)("button",{type:"button",className:"print-handout print-hidden","aria-label":"Print or save this handout as a PDF",onClick:function(){return"undefined"!=typeof window&&window.print()},children:[(0,t.jsx)("span",{"aria-hidden":"true",children:"\ud83d\udda8 "}),i]})}},8453(e,n,i){i.d(n,{R:()=>r,x:()=>s});var t=i(6540);const o={},a=t.createContext(o);function r(e){const n=t.useContext(a);return t.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:r(e.components),t.createElement(a.Provider,{value:n},e.children)}}}]);